### Normalizing an Array to the Nearest Prime Number

Below is a Python solution that uses the Sieve of Eratosthenes algorithm to generate prime numbers up to a certain limit. This solution efficiently handles large arrays and ensures accurate normalization.

```python
import math

def sieve_of_eratosthenes(limit):
    """Generate prime numbers up to the given limit."""
    sieve = [True] * (limit + 1)
    sieve[0:2] = [False, False]  # 0 and 1 are not prime numbers

    for num in range(2, int(math.sqrt(limit)) + 1):
        if sieve[num]:
            for multiple in range(num * num, limit + 1, num):
                sieve[multiple] = False

    return [num for num, is_prime in enumerate(sieve) if is_prime]


def is_prime(n):
    """Check if a number is prime."""
    if n < 2:
        return False
    for i in range(2, int(math.sqrt(n)) + 1):
        if n % i == 0:
            return False
    return True


def nearest_prime(n):
    """Find the nearest prime number greater than n."""
    limit = n * 2  # initial limit for the sieve
    while True:
        primes = sieve_of_eratosthenes(limit)
        if n in primes:
            return n
        if primes[-1] > n:
            return primes[-1]
        limit *= 2


def normalize_array(arr):
    """Normalize the array such that it adds up to the nearest prime number greater than the sum of all elements."""
    total_sum = sum(arr)
    nearest_prime_sum = nearest_prime(total_sum)
    normalization_factor = nearest_prime_sum / total_sum
    normalized_arr = [round(num * normalization_factor) for num in arr]
    return normalized_arr


# Unit tests
import unittest

class TestNormalization(unittest.TestCase):
    def test_duplicate_elements(self):
        arr = [1, 2, 2, 3, 3, 3]
        normalized_arr = normalize_array(arr)
        self.assertEqual(sum(normalized_arr), nearest_prime(sum(arr)))

    def test_max_element_value(self):
        arr = [10**9] * 1000
        normalized_arr = normalize_array(arr)
        self.assertEqual(sum(normalized_arr), nearest_prime(sum(arr)))

    def test_array_length(self):
        arr = [1] * 10**6
        normalized_arr = normalize_array(arr)
        self.assertEqual(sum(normalized_arr), nearest_prime(sum(arr)))

    def test_array_with_primes(self):
        arr = [2, 3, 5, 7, 11]
        normalized_arr = normalize_array(arr)
        self.assertEqual(sum(normalized_arr), nearest_prime(sum(arr)))

    def test_array_with_non_primes(self):
        arr = [4, 6, 8, 9, 10]
        normalized_arr = normalize_array(arr)
        self.assertEqual(sum(normalized_arr), nearest_prime(sum(arr)))

if __name__ == '__main__':
    unittest.main()
```

This solution first generates prime numbers up to a certain limit using the Sieve of Eratosthenes algorithm. It then finds the nearest prime number greater than the sum of the array elements. The normalization factor is calculated as a floating-point number, and the normalized array is created by multiplying each element with the normalization factor and rounding to the nearest integer. The unit tests cover various edge cases, including arrays with duplicate elements, maximum element values, and different lengths.

