To solve this task, we can iterate over the values of the dictionary and check if each value meets the given conditions. We will use helper functions to determine if a number is divisible by 3 and if it contains a prime number in its prime factorization.

Here's the Python code to solve the task:

```python
import math

def is_divisible_by_3(n):
    return n % 3 == 0

def has_prime_factor(n):
    # Check if n has any prime factor
    for i in range(2, int(math.sqrt(n))+1):
        if n % i == 0:
            return True
    return False

def get_max_values(d):
    max_values = {}

    for key, value in d.items():
        if isinstance(value, int) and is_divisible_by_3(value) and has_prime_factor(value):
            if key not in max_values or value > max_values[key]:
                max_values[key] = value
        else:
            max_values[key] = 0

    return max_values

# Example usage:
d = {'a': 12, 'b': 20, 'c': 30}
max_values = get_max_values(d)
print(max_values)
```

