Here's an implementation of the dictionary in Python:

```python
class LimitedDict:
    def __init__(self):
        self.capacity = 1000
        self.size = 0
        self.keys = [None] * self.capacity
        self.values = [None] * self.capacity
        self.key_to_index = {}

    def _hash(self, key):
        return hash(key) % self.capacity

    def _resize(self):
        new_capacity = self.capacity * 2
        new_keys = [None] * new_capacity
        new_values = [None] * new_capacity
        new_key_to_index = {}

        for i in range(self.capacity):
            if self.keys[i] is not None:
                new_index = self._hash(self.keys[i])
                while new_keys[new_index] is not None:
                    new_index = (new_index + 1) % new_capacity
                new_keys[new_index] = self.keys[i]
                new_values[new_index] = self.values[i]
                new_key_to_index[self.keys[i]] = new_index

        self.capacity = new_capacity
        self.keys = new_keys
        self.values = new_values
        self.key_to_index = new_key_to_index

    def add(self, key, value):
        if not isinstance(key, int) or key <= 0:
            raise ValueError("Key must be a positive integer")
        if not isinstance(value, str) or not value.islower() or len(value) == 0:
            raise ValueError("Value must be a non-empty lowercase string")

        if self.size == self.capacity:
            self._resize()

        if key in self.key_to_index:
            raise ValueError("Key already exists in the dictionary")

        index = self._hash(key)
        while self.keys[index] is not None:
            index = (index + 1) % self.capacity
        self.keys[index] = key
        self.values[index] = value
        self.key_to_index[key] = index
        self.size += 1

    def get(self, key):
        if not isinstance(key, int) or key <= 0:
            raise ValueError("Key must be a positive integer")
        if key in self.key_to_index:
            index = self.key_to_index[key]
            return self.values[index]
        return None

    def update(self, key, value):
        if not isinstance(key, int) or key <= 0:
            raise ValueError("Key must be a positive integer")
        if not isinstance(value, str) or not value.islower() or len(value) == 0:
            raise ValueError("Value must be a non-empty lowercase string")
        if key in self.key_to_index:
            index = self.key_to_index[key]
            self.values[index] = value

    def remove(self, key):
        if not isinstance(key, int) or key <= 0:
            raise ValueError("Key must be a positive integer")
        if key in self.key_to_index:
            index = self.key_to_index[key]
            self.keys[index] = None
            self.values[index] = None
            del self.key_to_index[key]
            self.size -= 1

    def exists(self, key):
        if not isinstance(key, int) or key <= 0:
            raise ValueError("Key must be a positive integer")
        return key in self.key_to_index

# Example usage:
dict = LimitedDict()
dict.add(1, "hello")
dict.add(2, "world")
print(dict.get(1))  # Output: hello
dict.update(1, "foo")
print(dict.get(1))  # Output: foo
dict.remove(2)
print(dict.exists(2))  # Output: False
```

This implementation uses a hash table to store the key-value pairs. The `add` method checks if the key already exists in the dictionary and raises a `ValueError` if it does. The `get` method checks if the key exists in the dictionary and returns `None` if it doesn't. The `update` method updates the value associated with a given key if the key exists in the dictionary. The `remove` method removes an entry from the dictionary with a given key if the key exists in the dictionary. The `exists` method checks if a key exists in the dictionary and returns `True` if it does, `False` otherwise.

The time complexity for each operation is O(1) on average, assuming a good hash function. The dictionary has a maximum capacity of 1000 entries. If the dictionary is full, the `add` method resizes the dictionary to twice its current capacity.

