class TrieNode:
    """A node in the Trie data structure."""

    def __init__(self):
        # Initialize a dictionary to store children nodes
        self.children = {}
        # Initialize a counter to store the frequency of the word
        self.count = 0
        # Initialize a flag to indicate if the word is complete
        self.is_end_of_word = False


class Trie:
    """A Trie data structure that supports insertion, deletion, search, prefix search, and frequency retrieval."""

    def __init__(self):
        # Initialize the root node
        self.root = TrieNode()

    def _insert(self, word):
        """Insert a word into the Trie."""

        node = self.root
        for char in word:
            if char not in node.children:
                node.children[char] = TrieNode()
            node = node.children[char]
        node.is_end_of_word = True
        node.count += 1

    def insert(self, word):
        """Insert a word into the Trie, handling duplicate words gracefully."""

        if word in self:
            self._increment_count(word)
        else:
            self._insert(word)

    def _delete(self, word):
        """Delete a word from the Trie."""

        def _delete_recursive(node, word, index):
            if index == len(word):
                if not node.is_end_of_word:
                    return False
                node.is_end_of_word = False
                return len(node.children) == 0
            char = word[index]
            if char not in node.children:
                return False
            should_delete_current_node = _delete_recursive(node.children[char], word, index + 1)
            if should_delete_current_node:
                del node.children[char]
                return len(node.children) == 0
            return False

        _delete_recursive(self.root, word, 0)

    def delete(self, word):
        """Delete a word from the Trie, handling invalid operations."""

        if word in self:
            self._delete(word)
        else:
            raise ValueError(f"Word '{word}' does not exist in the Trie.")

    def _search(self, word):
        """Search for a word in the Trie."""

        node = self.root
        for char in word:
            if char not in node.children:
                return False
            node = node.children[char]
        return node.is_end_of_word

    def search(self, word):
        """Search for a word in the Trie."""

        return self._search(word)

    def _prefix_search(self, prefix):
        """Search for all words with a specific prefix."""

        node = self.root
        for char in prefix:
            if char not in node.children:
                return []
            node = node.children[char]
        return self._get_words(node, prefix)

    def prefix_search(self, prefix):
        """Search for all words with a specific prefix."""

        return self._prefix_search(prefix)

    def _get_words(self, node, prefix):
        """Get all words starting from a given node."""

        words = []
        if node.is_end_of_word:
            words.append(prefix)
        for char, child_node in node.children.items():
            words.extend(self._get_words(child_node, prefix + char))
        return words

    def _increment_count(self, word):
        """Increment the count of a word in the Trie."""

        node = self.root
        for char in word:
            node = node.children[char]
        node.count += 1

    def _decrement_count(self, word):
        """Decrement the count of a word in the Trie."""

        node = self.root
        for char in word:
            node = node.children[char]
        node.count -= 1

    def most_frequent(self, prefix, k):
        """Find the k most frequent words with a given prefix."""

        words = self.prefix_search(prefix)
        word_freq = {}
        for word in words:
            word_freq[word] = self[word].count
        return sorted(word_freq.items(), key=lambda x: x[1], reverse=True)[:k]

    def __contains__(self, word):
        """Check if a word exists in the Trie."""

        return self._search(word)

    def __getitem__(self, word):
        """Get the count of a word in the Trie."""

        node = self.root
        for char in word:
            if char not in node.children:
                raise KeyError(f"Word '{word}' does not exist in the Trie.")
            node = node.children[char]
        return node.count


