        trie.insert("apple")
        trie.insert("banana")
        trie.insert("orange")
        trie.insert("app")
        self.assertEqual(trie.prefix_search("app"), ["apple", "app"])
        self.assertEqual(trie.prefix_search("ban"), ["banana"])

    def test_most_frequent(self):
