    if not isinstance(address, dict) or 'street' not in address or 'city' not in address or 'state' not in address or 'country' not in address:
        raise ValueError("Address must be an object with properties: street, city, state, and country")

    # Check if contact is an object with the required properties
    contact = data['contact']
    if not isinstance(contact, dict) or 'email' not in contact or 'phone' not in contact:
        raise ValueError("Contact must be an object with properties: email and phone")

    # Check if hobbies is an array of strings
    hobbies = data['hobbies']
    if not isinstance(hobbies, list) or not all(isinstance(hobby, str) for hobby in hobbies):
        raise ValueError("Hobbies must be an array of strings")

    # Check if languages is an object with boolean values for the properties
    languages = data['languages']
    if not isinstance(languages, dict) or not all(isinstance(value, bool) for value in languages.values()):
        raise ValueError("Languages must be an object with boolean values")

    # Check if education is an object with the required properties
    education = data['education']
    if not isinstance(education, dict) or 'degree' not in education or 'major' not in education or 'university' not in education:
        raise ValueError("Education must be an object with properties: degree, major, and university")

    # Check if experience is an array of objects with the required properties
    experience = data['experience']
    if not isinstance(experience, list) or not all(isinstance(exp, dict) and 'company' in exp and 'position' in exp and 'years' in exp for exp in experience):
