    # Perform additional validations
    if not re.match(r"[^@]+@[^@]+\.[^@]+", contact['email']):
        raise ValueError("Invalid email address")

    if not re.match(r"\+\d{1,2} \d{3}-\d{3}-\d{4}", contact['phone']):
        raise ValueError("Invalid phone number")

    if not all(isinstance(exp['years'], int) and exp['years'] > 0 for exp in experience):
        raise ValueError("Years in experience must be positive integers")

    # Format the JSON data
    formatted_data = {
