def validate_and_format_json(json_data):
    """
    Validates and formats the given JSON data based on a specific schema.

    Args:
        json_data (str): The JSON data to be validated and formatted.

    Returns:
        str: The formatted JSON data as a string if it is valid according to the schema and the additional validations.

    Raises:
        ValueError: If the JSON data is invalid or does not match the schema.
