    # Validate the "age" field
    if not isinstance(data["age"], int) or data["age"] <= 0:
        raise ValueError("Invalid age: must be a positive integer")

    # Validate the "address" field
    if not isinstance(data["address"], dict) or not all(field in data["address"] for field in ["street", "city", "state", "country"]):
        raise ValueError("Invalid address: must be an object with street, city, state, and country properties")

    # Validate the "contact" field
