The following algorithm uses a modified Manacher's algorithm to efficiently find the longest palindromic substring in a given character sequence. This approach ensures a time complexity of O(n) and a space complexity of O(n), where n is the length of the sequence.

### Code

```c
#include <stdio.h>
#include <stdlib.h>

// Structure to represent a node in the palindrome table
typedef struct Node {
    int length;
    int center;
} Node;

// Function to find the longest palindromic substring
char* longest_palindromic_substring(const char* sequence) {
    int n = 0;
    while (sequence[n] != '\0') {
        n++;
    }

    // Create a new string with a special character in the middle
    char* new_sequence = (char*)malloc((n * 2 + 3) * sizeof(char));
    new_sequence[0] = '#';
    int i = 0;
    while (sequence[i] != '\0') {
        new_sequence[n * 2 + 2] = '#';
        new_sequence[n * 2 + 1] = sequence[i];
        new_sequence[n * 2] = '#';
        i++;
    }
    new_sequence[n * 2 + 1] = '\0';

    // Initialize the palindrome table
    Node* palindrome_table = (Node*)malloc((n * 2 + 3) * sizeof(Node));
    int max_length = 0;
    int center = 0;

    // Iterate over the new sequence to fill the palindrome table
    for (int i = 0; i < n * 2 + 3; i++) {
        if (i == 0 || i == 1 || i == n * 2 + 1) {
            palindrome_table[i].length = 0;
            palindrome_table[i].center = 0;
        } else if (i <= center + max_length && palindrome_table[2 * center - i].length != 0) {
            int mirror = 2 * center - i;
            palindrome_table[i].length = palindrome_table[mirror].length;
            palindrome_table[i].center = mirror;
        } else {
            palindrome_table[i].length = 0;
            palindrome_table[i].center = 0;

            int left = i - 1;
            int right = i + 1;
            while (left >= 0 && right <= n * 2 + 1 && new_sequence[left] == new_sequence[right]) {
                palindrome_table[i].length++;
                left--;
                right++;
            }
            center = i;
            max_length = max(max_length, palindrome_table[i].length);
        }
    }

    // Find the center of the longest palindromic substring
    int max_center = 0;
    for (int i = 0; i < n * 2 + 3; i++) {
        if (palindrome_table[i].length > palindrome_table[max_center].length) {
            max_center = i;
        }
    }

    // Extract the longest palindromic substring
    int start = max_center - palindrome_table[max_center].length - 1;
    int end = max_center + palindrome_table[max_center].length;
    char* longest_palindromic_substring = (char*)malloc((end - start) * sizeof(char));
    for (int i = start + 1; i < end; i++) {
        if (new_sequence[i] == '#') {
            continue;
        }
        longest_palindromic_substring[i - start - 1] = new_sequence[i];
    }
    longest_palindromic_substring[end - start - 1] = '\0';

    // Free allocated memory
    free(new_sequence);
    free(palindrome_table);

    return longest_palindromic_substring;
}

int main() {
    const char* sequence = "babad";
    char* longest_palindromic_substring = longest_palindromic_substring(sequence);
    printf("Longest palindromic substring: %s\n", longest_palindromic_substring);
    free(longest_palindromic_substring);
    return 0;
}
