```python
def count_char_in_string(s, char):
    """
    Counts the occurrences of a character in a string, ignoring occurrences within parentheses, curly brackets, and quotes.

    Args:
        s (str): The input string.
        char (str): The character to count.

    Returns:
        int: The number of occurrences of the character in the string.
    """
    count = 0
    stack = []
    in_quote = False
    for i, c in enumerate(s):
        if c in ['(', '{']:
            stack.append(c)
        elif c in [')', '}']:
            if stack and (c == ')' and stack[-1] == '(' or c == '}' and stack[-1] == '{'):
                stack.pop()
        elif c in ['"', "'"]:
            if not in_quote:
                in_quote = True
            else:
                in_quote = False
        elif not stack and not in_quote:
            if c == char:
                count += 1
    return count

# Unit tests
import unittest

class TestCountCharInString(unittest.TestCase):
    def test_empty_string(self):
        self.assertEqual(count_char_in_string("", 'o'), 0)

    def test_string_with_only_quotes(self):
        self.assertEqual(count_char_in_string("'", 'o'), 0)

    def test_string_with_only_brackets(self):
        self.assertEqual(count_char_in_string("({})'", 'o'), 0)

    def test_string_with_char(self):
        self.assertEqual(count_char_in_string("hello", 'o'), 2)

    def test_string_with_char_and_brackets(self):
        self.assertEqual(count_char_in_string("hello(how{are}you)", 'o'), 2)

    def test_string_with_char_and_quotes(self):
        self.assertEqual(count_char_in_string("hello 'hello'", 'o'), 3)

    def test_string_with_char_and_nested_brackets(self):
        self.assertEqual(count_char_in_string("hello(how{are}you)", 'o'), 2)

    def test_string_with_char_and_nested_quotes(self):
        self.assertEqual(count_char_in_string("hello 'hello'", 'o'), 3)

if __name__ == '__main__':
    unittest.main()
