import math
import copy

def replace_values(data):
    """
    Replaces special values in a nested list or dictionary with 0.
    Replaces positive even numbers with 1.

    Args:
        data: A nested list or dictionary.

    Returns:
        The modified data with special values replaced.
    """
    if isinstance(data, list):
        return [replace_values(item) if isinstance(item, (list, dict)) else 0 if item in [None, '', -math.inf, math.inf] else 1 if item > 0 and item % 2 == 0 else item for item in data]
    elif isinstance(data, dict):
        return {key: replace_values(value) if isinstance(value, (list, dict)) else 0 if value in [None, '', -math.inf, math.inf] else 1 if value > 0 and value % 2 == 0 else value for key, value in data.items()}
    else:
        return data

# Unit tests
import unittest

class TestReplaceValues(unittest.TestCase):
    def test_list(self):
        self.assertEqual(replace_values([5, -2, 3, None, '', math.inf]), [1, 0, 3, 0, 0, math.inf])
        self.assertEqual(replace_values([1, 2, 3, 4, 5]), [1, 1, 3, 1, 1])
        self.assertEqual(replace_values([1, [2, '', [None]], {'a': '', 'b': [3, None, '']}]), [1, [1, 0, [0]], {'a': 0, 'b': [3, 0, 0]}])

    def test_dict(self):
        self.assertEqual(replace_values({'a': 1, 'b': '', 'c': None, 'd': [1, '', None]}), {'a': 1, 'b': 0, 'c': 0, 'd': [1, 0, 0]})
        self.assertEqual(replace_values({'a': 1, 'b': 2, 'c': 3, 'd': 4}), {'a': 1, 'b': 1, 'c': 3, 'd': 1})

    def test_nested_list(self):
        self.assertEqual(replace_values([1, [2, '', [None]], {'a': '', 'b': [3, None, '']}]), [1, [1, 0, [0]], {'a': 0, 'b': [3, 0, 0]}])

    def test_nested_dict(self):
        self.assertEqual(replace_values({'a': 1, 'b': {'c': 2, 'd': [3, None, '']} }), {'a': 1, 'b': {'c': 2, 'd': [3, 0, 0]}})

    def test_mixed_types(self):
        self.assertEqual(replace_values([1, 'a', 2.5, None, '', math.inf]), [1, 'a', 2.5, 0, 0, math.inf])

if __name__ == '__main__':
    unittest.main()
