```python
def count_lowercase_alphabets(s):
    """
    Recursively counts the number of lowercase alphabets in a given string, 
    excluding 'a' and 'b'. Returns 0 for non-string input types.

    Args:
        s (str): The input string.

    Returns:
        int: The count of lowercase alphabets in the string.
    """
    # Base case: If the input is not a string, return 0.
    if not isinstance(s, str):
        return 0

    # Base case: If the string is empty, return 0.
    if len(s) == 0:
        return 0

    # Recursive case: If the first character is a lowercase alphabet between 'c' and 'z', 
    # count it and recurse on the rest of the string.
    if s[0].islower() and 'c' <= s[0] <= 'z' and s[0] not in 'ab':
        return 1 + count_lowercase_alphabets(s[1:])

    # Recursive case: If the first character is not a lowercase alphabet between 'c' and 'z', 
    # don't count it and recurse on the rest of the string.
    return count_lowercase_alphabets(s[1:])


import unittest

class TestCountLowercaseAlphabets(unittest.TestCase):
    def test_empty_string(self):
        self.assertEqual(count_lowercase_alphabets(""), 0)

    def test_string_with_only_special_characters(self):
