```python
def is_prime(n):
    """Check if a number is prime."""
    if n < 2:
        return False
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            return False
    return True

def is_palindrome(n):
    """Check if a number is a palindrome."""
    return str(n) == str(n)[::-1]

def sum_of_digits(n):
    """Calculate the sum of digits of a number."""
    return sum(int(digit) for digit in str(n))

def prime_palindromes_with_prime_digit_sum():
    """Generate a list of prime palindromes where the sum of digits is a prime number."""
    prime_palindromes = []
    for num in range(2, 1000):  # We'll check up to 1000
        if is_prime(num) and is_palindrome(num) and is_prime(sum_of_digits(num)):
            prime_palindromes.append(num)
    return list(set(prime_palindromes))  # Return a list of unique prime palindromes

# Generate the list of prime palindromes
prime_palindromes = prime_palindromes_with_prime_digit_sum()

# Print the result
print("List of prime palindromes where the sum of digits is a prime number:")
print(prime_palindromes)
```

