Here is a Python program that prints all prime numbers from 1 to 1000, inclusive, that are also Fibonacci numbers:

```python
def is_prime(n):
    if n < 2:
        return False
    for i in range(2, int(n ** 0.5) + 1):
        if n % i == 0:
            return False
    return True

def is_fibonacci(n):
    if n < 0:
        return False
    a, b = 0, 1
    while b < n:
        a, b = b, a + b
    return b == n

for num in range(1, 1001):
    if is_prime(num) and is_fibonacci(num):
        print(num)
