class HTMLParser:
    def __init__(self):
        self.stack = []
        self.text = ""

    def parse(self, html_string, tag):
        if not html_string:
            return ""

        self.stack = []
        self.text = ""
        self.parse_helper(html_string, tag)

        return self.text

    def parse_helper(self, html_string, tag):
        i = 0
        while i < len(html_string):
            if html_string[i] == '<':
                if html_string[i+1] == '/':
                    self.stack.pop()
                    i += 2
                    while html_string[i] != '>':
                        i += 1
                elif html_string[i+1] == ' ' or html_string[i+1] == '/':
                    self.stack.append(html_string[i+1:i+html_string[i+1:].find('>')+1])
                    i += html_string[i+1:].find('>') + 1
                else:
                    self.stack.append(html_string[i:i+html_string[i:].find('<')])
                    i += html_string[i:].find('<')
            else:
                if not self.stack or self.stack[-1] == tag:
                    self.text += html_string[i]
                i += 1

