        self.assertEqual(parser.parse("<div class='header'><span>Welcome</span><span>to</span><span>the</span><span>world</span></div>", "span"), "Welcome to the world")
        self.assertEqual(parser.parse("<div class='header'><span>Hello</span><span>World</span></div><div class='footer'><span>Goodbye</span><span>World</span></div>", "span"), "Hello World Goodbye World")

    def test_empty_html_string(self):
