Here is a Python solution for the problem:

```python
def longest_increasing_subsequence_with_sum(arr, target_sum):
    n = len(arr)
    dp = [[False] * (target_sum + 1) for _ in range(n)]
    sum_dp = [[0] * (target_sum + 1) for _ in range(n)]

    # Initialize the first row
    for j in range(target_sum + 1):
        if arr[0] <= j:
            dp[0][j] = True
            sum_dp[0][j] = 1
        else:
            dp[0][j] = False
            sum_dp[0][j] = 0

    # Fill up the dp and sum_dp arrays
    for i in range(1, n):
        for j in range(target_sum + 1):
            if arr[i] <= j:
                dp[i][j] = dp[i-1][j] or dp[i-1][j-arr[i]]
                if dp[i][j]:
                    sum_dp[i][j] = max(sum_dp[i-1][j], sum_dp[i-1][j-arr[i]] + 1)
                else:
                    sum_dp[i][j] = 0
            else:
                dp[i][j] = dp[i-1][j]
                sum_dp[i][j] = sum_dp[i-1][j]

    # Find the maximum length of a subsequence with sum greater than the target sum
    max_length = 0
    for i in range(n):
        for j in range(target_sum + 1):
            if dp[i][j] and j > target_sum / 2 and sum_dp[i][j] > max_length:
                max_length = sum_dp[i][j]

    # Find the longest increasing subsequence with sum greater than the target sum
    max_length_subsequence = []
    for i in range(n):
        for j in range(target_sum + 1):
            if dp[i][j] and j > target_sum / 2 and sum_dp[i][j] == max_length:
                subsequence = []
                k = i
                while k >= 0 and sum_dp[k][j] > 0:
                    subsequence.append(arr[k])
                    k = k - 1
                    j = j - arr[k]
                max_length_subsequence = max(max_length_subsequence, subsequence, key=len)

    return max_length_subsequence

arr = [10,22,9,33,21,50,41,60]
