```python
from flask import Flask, render_template, redirect, url_for
from flask_login import LoginManager, UserMixin, login_user, login_required, logout_user, current_user
from flask_wtf import FlaskForm
from wtforms import StringField, PasswordField, SubmitField
from wtforms.validators import DataRequired, Length
from werkzeug.security import generate_password_hash, check_password_hash
from flask_wtf.csrf import CSRFProtect
from flask_session import Session
import os

class User(UserMixin):
    def __init__(self, id, username, password):
        self.id = id
        self.username = username
        self.password = generate_password_hash(password)

    def check_password(self, password):
        return check_password_hash(self.password, password)

class LoginForm(FlaskForm):
    username = StringField('Username', validators=[DataRequired(), Length(min=4, max=25)])
    password = PasswordField('Password', validators=[DataRequired(), Length(min=8, max=80)])
    submit = SubmitField('Log In')

class RegisterForm(FlaskForm):
    username = StringField('Username', validators=[DataRequired(), Length(min=4, max=25)])
    password = PasswordField('Password', validators=[DataRequired(), Length(min=8, max=80)])
    submit = SubmitField('Register')

class UserDB:
    def __init__(self):
        self.users = {}

    def add_user(self, username, password):
        self.users[username] = User(len(self.users), username, password)

    def get_user(self, username):
        return self.users.get(username)

login_manager = LoginManager()
csrf = CSRFProtect()
app = Flask(__name__)
app.config['SECRET_KEY'] = os.urandom(24)
app.config['SESSION_PERMANENT'] = False
app.config['SESSION_TYPE'] = 'filesystem'
Session(app)
csrf.init_app(app)
login_manager.init_app(app)
login_manager.login_view = 'login'

@app.route('/')
def index():
    return render_template('index.html')

@app.route('/login', methods=['GET', 'POST'])
def login():
    form = LoginForm()
    if form.validate_on_submit():
        user = UserDB().get_user(form.username.data)
        if user and user.check_password(form.password.data):
            login_user(user)
            return redirect(url_for('protected'))
        else:
            return render_template('login.html', form=form, error='Invalid username or password')
    return render_template('login.html', form=form)

@app.route('/register', methods=['GET', 'POST'])
def register():
    form = RegisterForm()
    if form.validate_on_submit():
        UserDB().add_user(form.username.data, form.password.data)
        return redirect(url_for('login'))
    return render_template('register.html', form=form)

@app.route('/protected')
@login_required
def protected():
    return render_template('protected.html')

@app.route('/logout')
@login_required
def logout():
    logout_user()
    return redirect(url_for('index'))

@login_manager.user_loader
def load_user(user_id):
    user_db = UserDB()
    for user in user_db.users.values():
        if user.id == int(user_id):
            return user
    return None

if __name__ == '__main__':
    app.run(debug=True)
```

This application includes the following features:

1.  **User Authentication**: The application uses Flask-Login to manage user authentication. The `User` class represents a user with a unique ID, username, and hashed password. The `UserDB` class is a simple in-memory database to store users.
2.  **Login and Registration**: The application includes routes for login and registration. The login form is validated using Flask-WTF, and the application checks the username and password against the stored users. If the credentials are valid, the user is logged in using Flask-Login.
3.  **Protected Page**: The application includes a protected page that requires the user to be logged in. The `@login_required` decorator is used to protect the page.
4.  **Logout**: The application includes a logout route that logs out the current user using Flask-Login.
5.  **Error Handling**: The application handles invalid login attempts by displaying an error message on the login page.
6.  **Security**: The application uses a secret key for CSRF protection and stores passwords securely using hashing.
7.  **Template Rendering**: The application uses Jinja2 templates for rendering HTML pages.

To run the application, save the code in a file (e.g., `app.py`) and execute it using `python app.py`. Then, open a web browser and navigate to `http://localhost:5000` to access the application.

