        data = pd.DataFrame([
            {'Customer': 'John', 'Category': 'Electronics', 'Sales': 500},
            {'Customer': 'Mary', 'Category': 'Home', 'Sales': 300}
        ])
        expected_output = {'Total Sales': 800, 'Most Popular Category': 'Electronics'}
        self.assertEqual(task_func(data), expected_output)
