import math
import re

class Runtime:
    def __init__(self):
        self.variables = {}
        self.functions = {}
        self.builtins = {
            'sin': math.sin,
            'cos': math.cos,
            'tan': math.tan,
            'asin': math.asin,
            'acos': math.acos,
            'atan': math.atan
        }

    def execute(self, statement):
        if re.match(r'^[a-zA-Z_][a-zA-Z0-9_]*\s*=\s*.*$', statement):
            self.assign_variable(statement)
        elif re.match(r'^[a-zA-Z_][a-zA-Z0-9_]*\s*:\s*.*$', statement):
            self.define_function(statement)
        else:
            try:
                result = self.evaluate_expression(statement)
                print(f"Result: {result}")
            except Exception as e:
                print(f"Error: {str(e)}")

    def assign_variable(self, statement):
        match = re.match(r'([a-zA-Z_][a-zA-Z0-9_]*)\s*=\s*(.*)', statement)
        if match:
            var_name = match.group(1)
            value = self.evaluate_expression(match.group(2))
            self.variables[var_name] = value
            print(f"Variable '{var_name}' assigned to {value}")
        else:
            print("Invalid variable assignment")

    def define_function(self, statement):
        match = re.match(r'([a-zA-Z_][a-zA-Z0-9_]*)\s*:\s*(.*)', statement)
        if match:
            func_name = match.group(1)
            func_body = match.group(2)
            self.functions[func_name] = func_body
            print(f"Function '{func_name}' defined")
        else:
            print("Invalid function definition")

    def evaluate_expression(self, expression):
        # Replace built-in functions with their Python equivalents
        for func_name, func in self.builtins.items():
            expression = re.sub(r'\b' + func_name + r'\(([^)]*)\)', f'func({re.escape($1)})', expression)

        # Replace user-defined functions with their Python equivalents
        for func_name, func_body in self.functions.items():
            expression = re.sub(r'\b' + func_name + r'\(([^)]*)\)', f'eval({re.escape(func_body)}, {re.escape(self.variables)})({re.escape($1)})', expression)

        # Replace variables with their values
        for var_name, value in self.variables.items():
            expression = re.sub(r'\b' + var_name + r'\b', str(value), expression)

        # Evaluate the expression
        try:
            return eval(expression)
        except Exception as e:
            raise Exception(f"Error evaluating expression: {str(e)}")

    def start_shell(self):
        while True:
            user_input = input(">>> ")
            if user_input == "exit()":
                break
            elif user_input.startswith("list variables"):
                print("Variables:")
                for var_name in self.variables:
                    print(f"- {var_name}: {self.variables[var_name]}")
            elif user_input.startswith("list functions"):
                print("Functions:")
                for func_name in self.functions:
                    print(f"- {func_name}")
            else:
                self.execute(user_input)

if __name__ == "__main__":
    runtime = Runtime()
    runtime.start_shell()
