# Example implementation of ResultProcessor
class ResultProcessor:
    def run(self, result, per_page=None):
        """
        Process paginated results from an API.

        Args:
            result (dict): A dictionary containing a 'data' list and a 'metadata' dictionary.
            per_page (int, optional): The number of items per page. Defaults to None.

        Returns:
            dict: A new dictionary with the processed data and metadata.

        Raises:
            ValueError: If the 'metadata' dictionary does not contain a 'page' key.
        """
        if 'metadata' not in result or 'page' not in result['metadata']:
            raise ValueError("Metadata must contain a 'page' key")

        # Get the current page number and the total number of items
        current_page = result['metadata']['page']
        total_items = result['metadata'].get('total', 0)

        # If per_page is not provided, return all items
        if per_page is None:
            per_page = total_items

        # Calculate the start and end indices for the current page
        start = (current_page - 1) * per_page
        end = start + per_page

        # Ensure that the end index does not exceed the total number of items
        end = min(end, total_items)

        # Return a new dictionary with the processed data and metadata
        return {
            'data': result['data'][start:end],
            'metadata': {
                'page': current_page,
                'perPage': per_page
            }
        }
