**server.py**
```python
import socket
import threading
import pickle
import random
import time
import os

# Configuration file management
config_file = 'server.config'
config = {}

try:
    with open(config_file, 'r') as f:
        for line in f:
            key, value = line.strip().split('=')
            config[key] = value
except FileNotFoundError:
    config['ip'] = 'localhost'
    config['port'] = '8080'

# Server settings
MAX_CLIENTS = 100
BUFFER_SIZE = 1024

class Player:
    def __init__(self, id, name, skin, x, y, color):
        self.id = id
        self.name = name
        self.skin = skin
        self.x = x
        self.y = y
        self.color = color
        self.score = 0

class Server:
    def __init__(self):
        self.players = {}
        self.lock = threading.Lock()

    def generate_color(self):
        while True:
            r = random.randint(0, 255)
            g = random.randint(0, 255)
            b = random.randint(0, 255)
            if r + g + b < 720:
                return (r, g, b)

    def handle_client(self, client_socket):
        while True:
            try:
                data = client_socket.recv(BUFFER_SIZE)
                if not data:
                    break
                command, *args = pickle.loads(data)
                with self.lock:
                    if command == 'move':
                        x, y = args
                        self.players[client_socket.getpeername()[0]].x = x
                        self.players[client_socket.getpeername()[0]].y = y
                    elif command == 'id':
                        client_socket.send(pickle.dumps(self.players[client_socket.getpeername()[0]].id))
                    elif command == 'get':
                        players_data = [player.__dict__ for player in self.players.values()]
                        client_socket.send(pickle.dumps(players_data))
            except Exception as e:
                print(f"Error handling client: {e}")
                break
        self.remove_player(client_socket)

    def remove_player(self, client_socket):
        with self.lock:
            if client_socket.getpeername()[0] in self.players:
                del self.players[client_socket.getpeername()[0]]

    def start(self):
        server_socket = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        server_socket.bind((config['ip'], int(config['port'])))
        server_socket.listen(MAX_CLIENTS)
        print(f"Server listening on {config['ip']}:{config['port']}")

        while True:
            client_socket, address = server_socket.accept()
            print(f"New client connected: {address}")
            with self.lock:
                if address[0] not in self.players:
                    self.players[address[0]] = Player(address[0], f"Player {len(self.players) + 1}", random.randint(0, 100), random.randint(0, 100), random.randint(0, 100), self.generate_color())
                    client_socket.send(pickle.dumps(self.players[address[0]].id))
            threading.Thread(target=self.handle_client, args=(client_socket,)).start()

if __name__ == "__main__":
    server = Server()
    server.start()
```

