import socket
import pickle

class Client:
    def __init__(self, ip, port):
        self.ip = ip
        self.port = port
        self.socket = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        self.socket.connect((ip, port))

    def send_command(self, command, *args):
        data = pickle.dumps((command, *args))
        self.socket.send(data)

    def get_player_id(self):
        self.socket.send(pickle.dumps('id'))
        return pickle.loads(self.socket.recv(1024))

    def get_game_state(self):
        self.socket.send(pickle.dumps('get'))
        return pickle.loads(self.socket.recv(1024))

    def close(self):
        self.socket.close()

if __name__ == "__main__":
    client = Client('localhost', 8080)
    while True:
        command = input("Enter command (move x y, id, get): ")
        if command == 'id':
            print(client.get_player_id())
        elif command.startswith('move'):
            x, y = map(int, command.split()[1:])
            client.send_command('move', x, y)
        elif command == 'get':
            print(client.get_game_state())
        else:
