                        new_cells[x][y] = True
                else:
                    if live_neighbors == 3:
                        new_cells[x][y] = True
        self.cells = new_cells

    def count_live_neighbors(self, x, y):
        count = 0
        for i in range(-1, 2):
            for j in range(-1, 2):
                if i == 0 and j == 0:
                    continue
                nx, ny = x + i, y + j
                if nx < 0 or nx >= GRID_SIZE[0] or ny < 0 or ny >= GRID_SIZE[1]:
                    continue
                if self.cells[nx][ny]:
                    count += 1
        return count

def draw_menu(window, font):
    menu_text = ["Configure Cells Manually", "Start the Game"]
    for i, text in enumerate(menu_text):
        text_surface = font.render(text, True, WHITE)
        window.blit(text_surface, (10, 10 + i * 40))

def main():
    grid = Grid()
    running = False
    menu_index = 0
    while True:
        for event in pygame.event.get():
            if event.type == pygame.QUIT:
                pygame.quit()
                sys.exit()
            elif event.type == pygame.MOUSEBUTTONDOWN:
                if not running:
                    if 10 <= event.pos[0] <= 200 and 10 + menu_index * 40 <= event.pos[1] <= 50 + menu_index * 40:
                        if menu_index == 0:
                            running = True
                        elif menu_index == 1:
                            running = True
                            grid = Grid()
                            for x in range(GRID_SIZE[0]):
                                for y in range(GRID_SIZE[1]):
                                    if random.random() < 0.5:
                                        grid.cells[x][y] = True
                        menu_index = (menu_index + 1) % 2
                    else:
                        x = event.pos[0] // CELL_SIZE
                        y = event.pos[1] // CELL_SIZE
                        if 0 <= x < GRID_SIZE[0] and 0 <= y < GRID_SIZE[1]:
                            grid.cells[x][y] = not grid.cells[x][y]
            elif event.type == pygame.KEYDOWN:
                if event.key == pygame.K_UP:
                    menu_index = (menu_index - 1) % 2
                elif event.key == pygame.K_DOWN:
                    menu_index = (menu_index + 1) % 2
                elif event.key == pygame.K_RETURN:
                    if menu_index == 0:
                        running = True
                    elif menu_index == 1:
                        running = True
                        grid = Grid()
                        for x in range(GRID_SIZE[0]):
                            for y in range(GRID_SIZE[1]):
                                if random.random() < 0.5:
                                    grid.cells[x][y] = True

        if running:
            grid.update()
            grid.draw(window)
            pygame.display.update()
            clock.tick(FPS)
        else:
            window.fill(BLACK)
            draw_menu(window, font)
            pygame.display.update()

class TestGrid(unittest.TestCase):
    def test_count_live_neighbors(self):
        grid = Grid()
        grid.cells[0][0] = True
        grid.cells[0][1] = True
        grid.cells[1][0] = True
        self.assertEqual(grid.count_live_neighbors(0, 0), 2)
        self.assertEqual(grid.count_live_neighbors(0, 1), 2)
        self.assertEqual(grid.count_live_neighbors(1, 0), 2)
        grid.cells[0][0] = False
        grid.cells[0][1] = False
        grid.cells[1][0] = False
        self.assertEqual(grid.count_live_neighbors(0, 0), 0)
        self.assertEqual(grid.count_live_neighbors(0, 1), 0)
        self.assertEqual(grid.count_live_neighbors(1, 0), 0)

