        query {
            jobPostingsByZipCodeAndCity(zipCode: 12345, city: "Test City") {
                id
                title
                description
                branch
                jobType
                zipCode
                city
            }
        }
    ''')

    assert result['errors'][0]['message'] == 'Not authenticated'

def test_job_postings_by_branch_and_job_type_unauthorized(client):
    result = client.execute('''
