@click.option('--username', help='Username to use for authentication.')
@click.option('--password', help='Password to use for authentication.', prompt=True, hide_input=True, confirmation_prompt=True)
@click.option('--cert', help='Path to the SSL certificate file.')
@click.option('--key', help='Path to the SSL key file.')
@click.option('--verify_ssl', help='Verify SSL certificate.', type=click.Choice(['true', 'false']), default='true')
@click.option('--format', help='Output format.', type=click.Choice(['json', 'toml']), default='toml')
@click.option('--dry_run', help='Perform a dry run.', type=click.Choice(['true', 'false']), default='false')
@click.option('--timeout', help='Timeout in seconds.', type=int, default=30)
@click.option('--verbose', help='Enable verbose mode.', type=click.Choice(['true', 'false']), default='false')
@click.option('--interactive', help='Interactive mode.', is_flag=True)
@click.option('--edit', help='Edit the configuration file in an external editor.', is_flag=True)
@click.option('--overwrite', help='Overwrite an existing configuration file.', is_flag=True)
@click.option('--file', help='Path to the configuration file.', default='config.toml')
def create(base_url, username, password, cert, key, verify_ssl, format, dry_run, timeout, verbose, interactive, edit, overwrite, file):
    """Create a new configuration file with default or user-provided values."""
    config = {
        'base_url': base_url,
        'username': username,
        'password': password,
        'cert': cert,
        'key': key,
        'verify_ssl': verify_ssl,
        'format': format,
        'dry_run': dry_run,
        'timeout': timeout,
        'verbose': verbose
    }

    if interactive:
        config = _get_config_interactive()
    elif edit:
        config = _edit_config(config, file)

    try:
        with open(file, 'w') as f:
            toml.dump(config, f)
        click.echo(f'Configuration file created successfully: {file}')
    except Exception as e:
        click.echo(f'Error creating configuration file: {e}')

@pulp_cli.command()
@click.option('--file', help='Path to the configuration file.', default='config.toml')
def edit(file):
    """Edit an existing configuration file in a text editor."""
    try:
        with open(file, 'r') as f:
            config = toml.load(f)
    except Exception as e:
        click.echo(f'Error loading configuration file: {e}')
        return

    with tempfile.NamedTemporaryFile(suffix='.tmp') as tmp:
        toml.dump(config, tmp)
        tmp.flush()
        os.startfile(tmp.name)
        shutil.move(tmp.name, file)
        click.echo(f'Configuration file edited successfully: {file}')

