```python
import json
import os
import shutil
import unittest
from typing import Dict, List

# Define the trait thresholds
trait_thresholds = {
    'Warmth': 0.5,
    'Reasoning': 0.5,
    'Emotional Stability': 0.5,
    'Dominance': 0.5,
    'Liveliness': 0.5,
    'Rule Consciousness': 0.5,
    'Social Boldness': 0.5,
    'Sensitivity': 0.5,
    'Vigilance': 0.5,
    'Abstractedness': 0.5,
    'Privateness': 0.5,
    'Apprehension': 0.5,
    'Openness to Change': 0.5,
    'Self-Reliance': 0.5,
    'Perfectionism': 0.5,
    'Tension': 0.5
}

def import_trait_values_and_image_identifiers(train_json_file: str, validation_json_file: str) -> (Dict[str, float], Dict[str, List[str]]):
    """
    Import the trait values and image identifiers from the JSON files.

    Args:
    train_json_file (str): The path to the JSON file containing the trait values and image identifiers for the training dataset.
    validation_json_file (str): The path to the JSON file containing the trait values and image identifiers for the validation dataset.

    Returns:
    A tuple containing two dictionaries: the first dictionary maps trait names to their corresponding values, and the second dictionary maps image identifiers to their corresponding trait values.
    """
    try:
        with open(train_json_file, 'r') as train_file:
            train_data = json.load(train_file)
    except FileNotFoundError:
        raise FileNotFoundError(f"Training JSON file not found: {train_json_file}")
    except json.JSONDecodeError:
        raise json.JSONDecodeError(f"Invalid JSON in training file: {train_json_file}")

    try:
        with open(validation_json_file, 'r') as validation_file:
            validation_data = json.load(validation_file)
    except FileNotFoundError:
        raise FileNotFoundError(f"Validation JSON file not found: {validation_json_file}")
    except json.JSONDecodeError:
        raise json.JSONDecodeError(f"Invalid JSON in validation file: {validation_json_file}")

    train_trait_values = {}
    train_image_identifiers = {}
    for image_id, trait_values in train_data.items():
        if 'trait_values' not in trait_values or 'image_identifier' not in trait_values:
            raise ValueError(f"Invalid JSON structure in training file: {train_json_file}")
        train_trait_values[image_id] = trait_values['trait_values']
        train_image_identifiers[image_id] = trait_values['image_identifier']

    validation_trait_values = {}
    validation_image_identifiers = {}
    for image_id, trait_values in validation_data.items():
        if 'trait_values' not in trait_values or 'image_identifier' not in trait_values:
            raise ValueError(f"Invalid JSON structure in validation file: {validation_json_file}")
        validation_trait_values[image_id] = trait_values['trait_values']
        validation_image_identifiers[image_id] = trait_values['image_identifier']

    return train_trait_values, train_image_identifiers, validation_trait_values, validation_image_identifiers

def extract_trait_values(trait_values: Dict[str, float]) -> List[float]:
    """
    Extract the trait values into a list.

    Args:
    trait_values (Dict[str, float]): A dictionary mapping trait names to their corresponding values.

    Returns:
    A list of trait values.
    """
    return list(trait_values.values())

def distribute_images_into_classification_folders(train_trait_values: Dict[str, float], train_image_identifiers: Dict[str, str], validation_trait_values: Dict[str, float], validation_image_identifiers: Dict[str, str], train_json_file: str, validation_json_file: str):
    """
    Distribute the images into the classification folders based on the trait values and thresholds.

    Args:
    train_trait_values (Dict[str, float]): A dictionary mapping image identifiers to their corresponding trait values for the training dataset.
    train_image_identifiers (Dict[str, str]): A dictionary mapping image identifiers to their corresponding trait values for the training dataset.
    validation_trait_values (Dict[str, float]): A dictionary mapping image identifiers to their corresponding trait values for the validation dataset.
    validation_image_identifiers (Dict[str, str]): A dictionary mapping image identifiers to their corresponding trait values for the validation dataset.
    train_json_file (str): The path to the JSON file containing the trait values and image identifiers for the training dataset.
    validation_json_file (str): The path to the JSON file containing the trait values and image identifiers for the validation dataset.
    """
    for trait, threshold in trait_thresholds.items():
        train_folder = f"../dataset/classification/train/{trait}/"
        validation_folder = f"../dataset/classification/validation/{trait}/"
        os.makedirs(train_folder, exist_ok=True)
        os.makedirs(validation_folder, exist_ok=True)

        for image_id, trait_value in train_trait_values.items():
            if trait_value > threshold:
                shutil.copy(train_image_identifiers[image_id], f"{train_folder}high-range/")
            else:
                shutil.copy(train_image_identifiers[image_id], f"{train_folder}low-range/")

        for image_id, trait_value in validation_trait_values.items():
            if trait_value > threshold:
                shutil.copy(validation_image_identifiers[image_id], f"{validation_folder}high-range/")
            else:
                shutil.copy(validation_image_identifiers[image_id], f"{validation_folder}low-range/")

class TestTraitValueImporter(unittest.TestCase):
