        self.assertEqual(train_trait_values, {"image1": {"Warmth": 0.6}, "image2": {"Warmth": 0.4}})
        self.assertEqual(train_image_identifiers, {"image1": "image1.jpg", "image2": "image2.jpg"})
        self.assertEqual(validation_trait_values, {"image3": {"Warmth": 0.7}, "image4": {"Warmth": 0.3}})
        self.assertEqual(validation_image_identifiers, {"image3": "image3.jpg", "image4": "image4.jpg"})

    def test_import_trait_values_and_image_identifiers_empty_json(self):
        train_json_file = "test_train.json"
        validation_json_file = "test_validation.json"
        with open(train_json_file, 'w') as train_file:
            json.dump({}, train_file)
        with open(validation_json_file, 'w') as validation_file:
            json.dump({}, validation_file)
