            import_trait_values_and_image_identifiers(train_json_file, validation_json_file)

    def test_import_trait_values_and_image_identifiers_missing_image_identifier(self):
        train_json_file = "test_train.json"
        validation_json_file = "test_validation.json"
        with open(train_json_file, 'w') as train_file:
            json.dump({
                "image1": {"trait_values": {"Warmth": 0.6}}
            }, train_file)
        with open(validation_json_file, 'w') as validation_file:
            json.dump({
                "image3": {"trait_values": {"Warmth": 0.7}}
            }, validation_file)
        with self.assertRaises(ValueError):
            import_trait_values_and_image_identifiers(train_json_file, validation_json_file)

class TestTraitValueExtractor(unittest.TestCase):
    def test_extract_trait_values(self):
        trait_values = {"Warmth": 0.6, "Reasoning": 0.4}
        self.assertEqual(extract_trait_values(trait_values), [0.6, 0.4])

class TestImageDistributor(unittest.TestCase):
    def test_distribute_images_into_classification_folders(self):
        train_trait_values = {"image1": {"Warmth": 0.6}, "image2": {"Warmth": 0.4}}
        train_image_identifiers = {"image1": "image1.jpg", "image2": "image2.jpg"}
