from rest_framework import status
from rest_framework.response import Response
from rest_framework.views import APIView
from rest_framework.permissions import IsAuthenticated
from .models import SocialAccount
from .serializers import SocialAccountSerializer

class SocialAccountView(APIView):
    permission_classes = [IsAuthenticated]

    def get(self, request):
        social_accounts = SocialAccount.objects.all()
        serializer = SocialAccountSerializer(social_accounts, many=True)
        return Response(serializer.data)

    def post(self, request):
        serializer = SocialAccountSerializer(data=request.data)
        if serializer.is_valid():
            serializer.save()
            return Response(serializer.data, status=status.HTTP_201_CREATED)
        return Response(serializer.errors, status=status.HTTP_400_BAD_REQUEST)

class SocialAccountDetailView(APIView):
    permission_classes = [IsAuthenticated]

    def get(self, request, pk):
        try:
            social_account = SocialAccount.objects.get(pk=pk)
        except SocialAccount.DoesNotExist:
            return Response(status=status.HTTP_404_NOT_FOUND)

        serializer = SocialAccountSerializer(social_account)
        return Response(serializer.data)

    def put(self, request, pk):
        try:
            social_account = SocialAccount.objects.get(pk=pk)
        except SocialAccount.DoesNotExist:
            return Response(status=status.HTTP_404_NOT_FOUND)

        serializer = SocialAccountSerializer(social_account, data=request.data)
        if serializer.is_valid():
            serializer.save()
            return Response(serializer.data)
        return Response(serializer.errors, status=status.HTTP_400_BAD_REQUEST)

    def delete(self, request, pk):
        try:
            social_account = SocialAccount.objects.get(pk=pk)
        except SocialAccount.DoesNotExist:
            return Response(status=status.HTTP_404_NOT_FOUND)

        social_account.delete()
        return Response(status=status.HTTP_204_NO_CONTENT)
