import subprocess
import sys

class EnvCheck:
    def __init__(self):
        self.cmd_check = CmdCheck()
        self.aapt_check = AAPTCheck()
        self.zipalign_check = ZIPALIGNCheck()

    def cmd_check(self):
        """Check if 'cmd' command is present and properly set up."""
        try:
            subprocess.check_output(['cmd', '/c', 'echo', 'Hello, World!'], stderr=subprocess.STDOUT)
            return True
        except subprocess.CalledProcessError:
            return False

    def aapt_check(self):
        """Check if 'aapt' command is present and properly set up."""
        try:
            subprocess.check_output(['aapt', 'dump', 'badging', 'android'], stderr=subprocess.STDOUT)
            return True
        except subprocess.CalledProcessError:
            return False

    def zipalign_check(self):
        """Check if 'zipalign' command is present and properly set up."""
        try:
            subprocess.check_output(['zipalign', '-v', '4', 'android'], stderr=subprocess.STDOUT)
            return True
        except subprocess.CalledProcessError:
            return False

    def pre_check(self):
        """Perform all environment checks and raise an exception if any check fails."""
        checks = [self.cmd_check, self.aapt_check, self.zipalign_check]
        for check in checks:
            if not check():
                raise SystemExit(f"Check failed: {check.__name__}")
        print("All checks passed.")


