        trip = Trip(350, 4)
        print(f"{trip.average_speed()} km/h")
        print(trip)

        # Attempt to set invalid distance and time
        trip.set_distance(-100)
        trip.set_time(0)
        print(trip)  # Should print the original valid state

    except ValueError as e:
        print(e)
