import re
import hashlib
import ipaddress
import typing
from typing import NamedTuple, List, Dict
from stix2 import MarkingDefinition, Label

class ObservableProperties(NamedTuple):
    """Properties for creating observables."""
    value: str
    creator: str
    labels: List[str]
    marking_definitions: List[MarkingDefinition]

def _validate_observable_value(value: str) -> bool:
    """Validate the format of the observable value."""
    if not value:
        return False
    if not re.match(r'^[a-zA-Z0-9._-]+$', value):
        return False
    return True

def _generate_default_custom_properties() -> ObservableProperties:
    """Generate default custom properties for observables."""
    return ObservableProperties(
        value='',
        creator='Unknown',
        labels=[],
        marking_definitions=[]
    )

def create_ipv4_address(properties: ObservableProperties) -> Dict:
    """
    Create an IPv4 address observable.

    Args:
    - properties: ObservableProperties instance with the value of the IPv4 address.

    Returns:
    - A dictionary representing the IPv4 address observable in STIX 2.0 format.
    """
    if not _validate_observable_value(properties.value):
        raise ValueError('Invalid IPv4 address format')
    try:
        ipaddress.IPv4Address(properties.value)
    except ipaddress.AddressValueError:
        raise ValueError('Invalid IPv4 address format')
    return {
        'type': 'ipv4-addr',
        'value': properties.value,
        'custom_properties': {
            'score': 0,
            'labels': properties.labels,
            'marking_definitions': [md.to_dict() for md in properties.marking_definitions]
        },
        'custom_properties_creator': properties.creator
    }

def create_ipv6_address(properties: ObservableProperties) -> Dict:
    """
    Create an IPv6 address observable.

    Args:
    - properties: ObservableProperties instance with the value of the IPv6 address.

    Returns:
    - A dictionary representing the IPv6 address observable in STIX 2.0 format.
    """
    if not _validate_observable_value(properties.value):
        raise ValueError('Invalid IPv6 address format')
    try:
        ipaddress.IPv6Address(properties.value)
    except ipaddress.AddressValueError:
        raise ValueError('Invalid IPv6 address format')
    return {
        'type': 'ipv6-addr',
        'value': properties.value,
        'custom_properties': {
            'score': 0,
            'labels': properties.labels,
            'marking_definitions': [md.to_dict() for md in properties.marking_definitions]
        },
        'custom_properties_creator': properties.creator
    }

def create_domain_name(properties: ObservableProperties) -> Dict:
    """
    Create a domain name observable.

    Args:
    - properties: ObservableProperties instance with the value of the domain name.

    Returns:
    - A dictionary representing the domain name observable in STIX 2.0 format.
    """
    if not _validate_observable_value(properties.value):
        raise ValueError('Invalid domain name format')
    return {
        'type': 'domain-name',
        'value': properties.value,
        'custom_properties': {
            'score': 0,
            'labels': properties.labels,
            'marking_definitions': [md.to_dict() for md in properties.marking_definitions]
        },
        'custom_properties_creator': properties.creator
    }

def create_hostname(properties: ObservableProperties) -> Dict:
    """
    Create a hostname observable.

    Args:
    - properties: ObservableProperties instance with the value of the hostname.

    Returns:
    - A dictionary representing the hostname observable in STIX 2.0 format.
    """
    if not _validate_observable_value(properties.value):
        raise ValueError('Invalid hostname format')
    return {
        'type': 'hostname',
        'value': properties.value,
        'custom_properties': {
            'score': 0,
            'labels': properties.labels,
            'marking_definitions': [md.to_dict() for md in properties.marking_definitions]
        },
        'custom_properties_creator': properties.creator
    }

def create_url(properties: ObservableProperties) -> Dict:
    """
    Create a URL observable.

    Args:
    - properties: ObservableProperties instance with the value of the URL.

    Returns:
    - A dictionary representing the URL observable in STIX 2.0 format.
    """
    if not _validate_observable_value(properties.value):
        raise ValueError('Invalid URL format')
    return {
        'type': 'url',
        'value': properties.value,
        'custom_properties': {
            'score': 0,
            'labels': properties.labels,
            'marking_definitions': [md.to_dict() for md in properties.marking_definitions]
        },
        'custom_properties_creator': properties.creator
    }

def create_file(properties: ObservableProperties) -> Dict:
    """
    Create a file observable.

    Args:
    - properties: ObservableProperties instance with the file name, MD5, SHA-1, and SHA-256 hashes.

    Returns:
    - A dictionary representing the file observable in STIX 2.0 format.
    """
    if not _validate_observable_value(properties.value):
        raise ValueError('Invalid file name format')
    if not _validate_observable_value(properties.value):
        raise ValueError('Invalid hash format')
    hashes = {
        'hashes': {
            'MD5': hashlib.md5(properties.value.encode()).hexdigest(),
            'SHA-1': hashlib.sha1(properties.value.encode()).hexdigest(),
            'SHA-256': hashlib.sha256(properties.value.encode()).hexdigest()
        }
    }
    return {
        'type': 'file',
        'value': properties.value,
        'custom_properties': {
            'score': 0,
            'labels': properties.labels,
            'marking_definitions': [md.to_dict() for md in properties.marking_definitions]
        },
        'custom_properties_creator': properties.creator,
        **hashes
    }

