        properties = ObservableProperties('2001:0db8:85a3:0000:0000:8a2e:0370:7334', 'John Doe', ['label1', 'label2'], [])
        self.assertEqual(create_ipv6_address(properties)['type'], 'ipv6-addr')

    def test_domain_name(self):
        properties = ObservableProperties('example.com', 'John Doe', ['label1', 'label2'], [])
        self.assertEqual(create_domain_name(properties)['type'], 'domain-name')

    def test_hostname(self):
        properties = ObservableProperties('example-hostname', 'John Doe', ['label1', 'label2'], [])
        self.assertEqual(create_hostname(properties)['type'], 'hostname')

    def test_url(self):
        properties = ObservableProperties('https://example.com', 'John Doe', ['label1', 'label2'], [])
        self.assertEqual(create_url(properties)['type'], 'url')

    def test_file(self):
        properties = ObservableProperties('example.txt', 'John Doe', ['label1', 'label2'], [])
        self.assertEqual(create_file(properties)['type'], 'file')

