            y = random.uniform(-10, 10)
            node_coords.append((x, y))
        return node_coords

    def calculate_distance(self, node1, node2):
        return math.sqrt((node1[0] - node2[0])**2 + (node1[1] - node2[1])**2)

    def calculate_total_cost(self):
        total_cost = 0
        for i in range(self.num_nodes):
            for j in range(i+1, self.num_nodes):
                if self.adj_matrix[i][j] == 1:
                    total_cost += self.calculate_distance(self.node_coords[i], self.node_coords[j])
        return total_cost

    def is_valid_graph(self):
        # Check if the graph is fully connected
        for i in range(self.num_nodes):
            for j in range(i+1, self.num_nodes):
                if self.adj_matrix[i][j] == 0:
                    return False

        # Check if the maximum diameter of the graph is 4
        max_diameter = 0
        for i in range(self.num_nodes):
            for j in range(i+1, self.num_nodes):
                if self.adj_matrix[i][j] == 1:
                    diameter = self.calculate_diameter(i, j)
                    max_diameter = max(max_diameter, diameter)
        if max_diameter > 4:
            return False

        # Check if each node has a degree of exactly 3
        for i in range(self.num_nodes):
            degree = 0
            for j in range(self.num_nodes):
                if self.adj_matrix[i][j] == 1:
                    degree += 1
            if degree != 3:
                return False

        return True

    def calculate_diameter(self, node1, node2):
        visited = [False for _ in range(self.num_nodes)]
        queue = [[node1, 0]]
        visited[node1] = True
        while queue:
            node, distance = queue.pop(0)
            if node == node2:
                return distance
            for i in range(self.num_nodes):
                if self.adj_matrix[node][i] == 1 and not visited[i]:
                    queue.append([i, distance + 1])
                    visited[i] = True
        return -1

    def remove_edge(self, i, j):
        self.adj_matrix[i][j] = 0
        self.adj_matrix[j][i] = 0

    def greedy_local_search(self):
        start_time = time.time()
        for _ in range(100):
            max_cost = 0
            max_i = -1
            max_j = -1
            for i in range(self.num_nodes):
                for j in range(i+1, self.num_nodes):
                    if self.adj_matrix[i][j] == 1:
                        cost = self.calculate_distance(self.node_coords[i], self.node_coords[j])
                        if cost > max_cost:
                            max_cost = cost
                            max_i = i
                            max_j = j
            if max_i != -1 and max_j != -1:
                self.remove_edge(max_i, max_j)
