                    self.adj_matrix[max_j][max_i] = 1
            else:
                break
        self.total_cost_after_optimization = self.calculate_total_cost()
        end_time = time.time()
        self.runtime_greedy_local_search = end_time - start_time

    def original_heuristic(self):
        start_time = time.time()
        self.adj_matrix = [[0 for _ in range(self.num_nodes)] for _ in range(self.num_nodes)]
        for i in range(self.num_nodes):
