            return
        self.total_cost_after_optimization = self.calculate_total_cost()
        end_time = time.time()
        self.runtime_original_heuristic = end_time - start_time

    def print_graph(self):
        print("Node Coordinates:")
        for i in range(self.num_nodes):
            print(f"Node {i+1}: ({self.node_coords[i][0]}, {self.node_coords[i][1]})")
        print("Adjacency Matrix:")
        for row in self.adj_matrix:
            print(row)
        print(f"Total Cost Before Optimization: {self.total_cost_before_optimization}")
        print(f"Total Cost After Optimization: {self.total_cost_after_optimization}")
        print(f"Runtime Greedy Local Search: {self.runtime_greedy_local_search} seconds")
        print(f"Runtime Original Heuristic: {self.runtime_original_heuristic} seconds")

