import pyinputplus as pyip

class Calculator:
    def __init__(self):
        pass

    def add(self, num1, num2):
        """Returns the sum of two numbers."""
        return num1 + num2

    def subtract(self, num1, num2):
        """Returns the difference of two numbers."""
        return num1 - num2

    def multiply(self, num1, num2):
        """Returns the product of two numbers."""
        return num1 * num2

    def divide(self, num1, num2):
        """Returns the quotient of two numbers. Raises a ValueError if num2 is zero."""
        if num2 == 0:
            raise ValueError("Cannot divide by zero.")
        return num1 / num2


def main():
    calculator = Calculator()

    while True:
        try:
            num1 = float(pyip.inputFloat("Enter the first number: "))
            num2 = float(pyip.inputFloat("Enter the second number: "))

            print("\nSelect an operation:")
            print("1. Addition")
            print("2. Subtraction")
            print("3. Multiplication")
            print("4. Division")

            choice = pyip.inputChoice("Enter your choice (1/2/3/4): ")

            if choice == "1":
                result = calculator.add(num1, num2)
                print(f"\n{num1} + {num2} = {result}")
            elif choice == "2":
                result = calculator.subtract(num1, num2)
                print(f"\n{num1} - {num2} = {result}")
            elif choice == "3":
                result = calculator.multiply(num1, num2)
                print(f"\n{num1} * {num2} = {result}")
            elif choice == "4":
                try:
                    result = calculator.divide(num1, num2)
                    print(f"\n{num1} / {num2} = {result}")
                except ValueError as e:
                    print(f"\nError: {e}")
            else:
                print("\nInvalid choice. Please try again.")

            cont = pyip.inputYesNo("\nDo you want to continue? (yes/no): ")
            if not cont.lower() == "yes":
                break

        except ValueError as e:
            print(f"\nError: {e}")


if __name__ == "__main__":
    main()
```

