```python
import datetime
import dateutil.parser
from typing import Union

class CongressError(Exception):
    """Custom exception class for general Congress API errors."""
    def __init__(self, message: str, response: dict = None, url: str = None):
        self.message = message
        self.response = response
        self.url = url
        super().__init__(message)

class NotFound(CongressError):
    """Subclass of CongressError for items not found in the API."""
    pass

def check_chamber(chamber: str) -> None:
    """Validate whether a given chamber is one of 'house', 'senate', or 'both'."""
    if chamber not in ['house', 'senate', 'both']:
        raise TypeError(f"Invalid chamber: {chamber}. Must be 'house', 'senate', or 'both'.")

def get_congress(year: int) -> int:
    """Calculate the Congress number based on a given year."""
    if year < 1789:
        raise CongressError(f"Year {year} is before the first Congress (1789).")
    return (year - 1789) // 2 + 1

def parse_date(date_str: Union[str, datetime.datetime, datetime.date]) -> datetime.datetime:
    """Parse a date string into a datetime object."""
    if isinstance(date_str, (datetime.datetime, datetime.date)):
        return date_str
    try:
        return dateutil.parser.parse(date_str)
    except (TypeError, ValueError):
        try:
            return datetime.datetime.strptime(date_str, '%Y-%m-%d')
        except ValueError:
            raise CongressError(f"Invalid date string: {date_str}")

def u(text: Union[bytes, str]) -> str:
    """Ensure a given text is returned as a Unicode string."""
    if isinstance(text, bytes):
        text = text.decode('utf-8', errors='replace')
    return text.replace('\r\n', '\n')

def get_offset(page: int) -> int:
    """Calculate the offset for pagination in the API."""
    if page < 1:
        raise CongressError(f"Page number {page} is less than 1.")
    return (page - 1) * 20

CURRENT_CONGRESS = get_congress(datetime.date.today().year)

# Test cases
import unittest

class TestCongressUtils(unittest.TestCase):
    def test_check_chamber(self):
        check_chamber('house')
        check_chamber('senate')
        check_chamber('both')
        with self.assertRaises(TypeError):
            check_chamber('invalid')

    def test_get_congress(self):
        self.assertEqual(get_congress(1789), 1)
        self.assertEqual(get_congress(1790), 2)
        with self.assertRaises(CongressError):
            get_congress(1788)

    def test_parse_date(self):
        self.assertEqual(parse_date('2022-01-01'), datetime.datetime(2022, 1, 1))
        self.assertEqual(parse_date(datetime.date(2022, 1, 1)), datetime.date(2022, 1, 1))
        with self.assertRaises(CongressError):
            parse_date('invalid')

    def test_u(self):
        self.assertEqual(u(b'Hello\r\nWorld'), 'Hello\nWorld')
        self.assertEqual(u('Hello\nWorld'), 'Hello\nWorld')

    def test_get_offset(self):
        self.assertEqual(get_offset(1), 0)
        self.assertEqual(get_offset(2), 20)
        with self.assertRaises(CongressError):
            get_offset(0)

if __name__ == '__main__':
    unittest.main()
```

