import unittest

# Define the base class Test
class Test:
    def __init__(self, name, description=None):
        self.name = name
        self.description = description

    @classmethod
    def description(cls):
        return cls.__doc__

    def name(self):
        return self.name


# Define the TestRegistry class
class TestRegistry:
    def __init__(self):
        self._registered_tests = {}

    def register(self, test_class):
        if not issubclass(test_class, Test):
            raise ValueError("Test class must inherit from Test")
        if test_class.name in self._registered_tests:
            raise ValueError(f"Test class with name '{test_class.name}' already registered")
        self._registered_tests[test_class.name] = test_class

    def get(self, name):
        if name not in self._registered_tests:
            raise ValueError(f"Test class with name '{name}' not found")
        return self._registered_tests[name]

    def list(self):
        return list(self._registered_tests.keys())


# Test cases
class TestRegistryTest(unittest.TestCase):
    def setUp(self):
        self.registry = TestRegistry()

    def test_register(self):
        class MyTest(Test):
            def __init__(self):
                super().__init__("MyTest")

        self.registry.register(MyTest)
        self.assertEqual(self.registry.list(), ["MyTest"])

    def test_register_duplicate(self):
        class MyTest(Test):
            def __init__(self):
                super().__init__("MyTest")

        self.registry.register(MyTest)
        with self.assertRaises(ValueError):
            self.registry.register(MyTest)

    def test_register_non_inheriting_class(self):
        class MyTest:
            def __init__(self):
                pass

        with self.assertRaises(ValueError):
            self.registry.register(MyTest)

    def test_get(self):
        class MyTest(Test):
            def __init__(self):
                super().__init__("MyTest")

        self.registry.register(MyTest)
        self.assertEqual(self.registry.get("MyTest").name(), "MyTest")

    def test_get_non_existent(self):
        with self.assertRaises(ValueError):
            self.registry.get("NonExistentTest")

    def test_list(self):
        class MyTest(Test):
            def __init__(self):
                super().__init__("MyTest")

        class AnotherTest(Test):
            def __init__(self):
                super().__init__("AnotherTest")

        self.registry.register(MyTest)
        self.registry.register(AnotherTest)
        self.assertEqual(self.registry.list(), ["MyTest", "AnotherTest"])


if __name__ == "__main__":
    unittest.main()
