from flask import Flask, request, jsonify
import numpy as np
from scipy import stats
from scipy.stats import norm
from scipy import stats as st
import matplotlib.pyplot as plt

app = Flask(__name__)

# Helper function to validate input data
def validate_input(data):
    if not isinstance(data, dict):
        return False
    if 'samples' not in data or not isinstance(data['samples'], list):
        return False
    for sample in data['samples']:
        if not isinstance(sample, list) or len(sample) < 2:
            return False
        for value in sample:
            if not isinstance(value, (int, float)):
                return False
    return True

# Helper function to perform a Z-test
def z_test(data):
    samples = data['samples']
    if len(samples) == 1:
        sample = samples[0]
        mean = np.mean(sample)
        std = np.std(sample, ddof=1)
        z_score = (mean - 0) / (std / np.sqrt(len(sample)))
        return {'z_score': z_score, 'p_value': stats.norm.sf(abs(z_score)) * 2}
    elif len(samples) == 2:
        sample1, sample2 = samples
        mean1, mean2 = np.mean(sample1), np.mean(sample2)
        std1, std2 = np.std(sample1, ddof=1), np.std(sample2, ddof=1)
        if len(sample1) < 30 or len(sample2) < 30:
            return {'error': 'Not enough data points for a Z-test. Consider using a T-test.'}
        z_score = (mean1 - mean2) / np.sqrt((std1**2 / len(sample1)) + (std2**2 / len(sample2)))
        return {'z_score': z_score, 'p_value': stats.norm.sf(abs(z_score)) * 2}
    else:
        return {'error': 'Invalid number of samples for a Z-test.'}

# Helper function to perform a T-test with equal variance
def t_test_equal_variance(data):
    samples = data['samples']
    if len(samples) != 2:
        return {'error': 'Invalid number of samples for a T-test with equal variance.'}
    sample1, sample2 = samples
    mean1, mean2 = np.mean(sample1), np.mean(sample2)
    std1, std2 = np.std(sample1, ddof=1), np.std(sample2, ddof=1)
    if len(sample1) < 30 or len(sample2) < 30:
        return {'error': 'Not enough data points for a T-test with equal variance. Consider using a T-test with unequal variance.'}
    t_stat, p_value = stats.ttest_ind(sample1, sample2, equal_var=True)
    return {'t_stat': t_stat, 'p_value': p_value}

# Helper function to perform a T-test with unequal variance
def t_test_unequal_variance(data):
    samples = data['samples']
    if len(samples) != 2:
        return {'error': 'Invalid number of samples for a T-test with unequal variance.'}
    sample1, sample2 = samples
    mean1, mean2 = np.mean(sample1), np.mean(sample2)
    std1, std2 = np.std(sample1, ddof=1), np.std(sample2, ddof=1)
    if len(sample1) < 30 or len(sample2) < 30:
        return {'error': 'Not enough data points for a T-test with unequal variance. Consider using a T-test with equal variance.'}
    t_stat, p_value = stats.ttest_ind(sample1, sample2, equal_var=False)
    return {'t_stat': t_stat, 'p_value': p_value}

