import re
from datetime import datetime

class DomainValidator:
    def __init__(self):
        pass

    @staticmethod
    def validate_domain(domain):
        """
        Validate a domain name.

        Args:
            domain (str): The domain name to validate.

        Returns:
            bool: True if the domain is valid, False otherwise.
        """
        pattern = r'^[a-zA-Z0-9.-]+\.[a-zA-Z]{2,}$'
        return bool(re.match(pattern, domain))

    @staticmethod
    def validate_ip(ip):
        """
        Validate an IP address.

        Args:
            ip (str): The IP address to validate.

        Returns:
            bool: True if the IP is valid, False otherwise.
        """
        pattern = r'^((25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)\.){3}(25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)$'
        return bool(re.match(pattern, ip))

    @staticmethod
    def convert_month(month):
        """
        Convert a month representation to a standardized short form.

        Args:
            month (str): The month representation to convert.

        Returns:
            str: The converted month in short form (e.g., "Jan" for "January").
        """
        month_map = {
            "jan": "Jan", "january": "Jan",
            "feb": "Feb", "february": "Feb",
            "mar": "Mar", "march": "Mar",
            "apr": "Apr", "april": "Apr",
            "may": "May",
            "jun": "Jun", "june": "Jun",
            "jul": "Jul", "july": "Jul",
            "aug": "Aug", "august": "Aug",
            "sep": "Sep", "september": "Sep",
            "oct": "Oct", "october": "Oct",
            "nov": "Nov", "november": "Nov",
            "dec": "Dec", "december": "Dec"
        }
        return month_map.get(month.lower(), month)

    @staticmethod
    def format_date(date_str):
        """
        Format a date string into a standard format ("DD-MMM-YYYY").

        Args:
            date_str (str): The date string to format.

        Returns:
            str: The formatted date string.
        """
        try:
            date = datetime.strptime(date_str, "%d %B %Y")
            return date.strftime("%d-%b-%Y")
        except ValueError:
            try:
                date = datetime.strptime(date_str, "%d %m %Y")
                return date.strftime("%d-%b-%Y")
            except ValueError:
                try:
                    date = datetime.strptime(date_str, "%d %b %Y")
                    return date.strftime("%d-%b-%Y")
                except ValueError:
                    return "Invalid date format"

    @staticmethod
    def format_date_with_leading_zeros(date_str):
        """
        Format a date string into a standard format ("DD-MMM-YYYY") with leading zeros.

        Args:
            date_str (str): The date string to format.

        Returns:
            str: The formatted date string.
        """
        try:
            date = datetime.strptime(date_str, "%d %B %Y")
            return date.strftime("%02d-%b-%Y")
        except ValueError:
            try:
                date = datetime.strptime(date_str, "%d %m %Y")
                return date.strftime("%02d-%b-%Y")
            except ValueError:
                try:
                    date = datetime.strptime(date_str, "%d %b %Y")
                    return date.strftime("%02d-%b-%Y")
                except ValueError:
                    return "Invalid date format"
