import unittest
from domain_validator import DomainValidator

class TestDomainValidator(unittest.TestCase):
    def test_validate_domain(self):
        self.assertTrue(DomainValidator.validate_domain("example.com"))
        self.assertFalse(DomainValidator.validate_domain("example"))
        self.assertFalse(DomainValidator.validate_domain("example.com.au.uk"))

    def test_validate_ip(self):
        self.assertTrue(DomainValidator.validate_ip("192.168.0.1"))
        self.assertFalse(DomainValidator.validate_ip("192.168.0"))
        self.assertFalse(DomainValidator.validate_ip("192.168.0.1.1"))

    def test_convert_month(self):
        self.assertEqual(DomainValidator.convert_month("jan"), "Jan")
        self.assertEqual(DomainValidator.convert_month("January"), "Jan")
        self.assertEqual(DomainValidator.convert_month("invalid"), "invalid")

    def test_format_date(self):
        self.assertEqual(DomainValidator.format_date("31 December 2022"), "31-Dec-2022")
        self.assertEqual(DomainValidator.format_date("31 12 2022"), "31-Dec-2022")
        self.assertEqual(DomainValidator.format_date("31 Dec 2022"), "31-Dec-2022")
        self.assertEqual(DomainValidator.format_date("invalid"), "Invalid date format")

    def test_format_date_with_leading_zeros(self):
        self.assertEqual(DomainValidator.format_date_with_leading_zeros("31 December 2022"), "31-Dec-2022")
        self.assertEqual(DomainValidator.format_date_with_leading_zeros("31 12 2022"), "31-Dec-2022")
        self.assertEqual(DomainValidator.format_date_with_leading_zeros("31 Dec 2022"), "31-Dec-2022")
        self.assertEqual(DomainValidator.format_date_with_leading_zeros("invalid"), "Invalid date format")

if __name__ == "__main__":
    unittest.main()
