```python
from datetime import timedelta, date

class Date:
    def __init__(self, init_day: int, init_month: int, init_year: int):
        self.set_year(init_year)
        self.set_month(init_month)
        self.set_day(init_day)

    def show(self):
        print("{:02d}-{:02d}-{:04d}".format(self.day, self.month, self.year))

    def set_day(self, new_day: int):
        if 1 <= new_day <= 31:
            self.day = new_day
        else:
            raise ValueError("Day must be between 1 and 31")

    def set_month(self, new_month: int):
        if 1 <= new_month <= 12:
            self.month = new_month
        else:
            raise ValueError("Month must be between 1 and 12")

    def set_year(self, new_year: int):
        if new_year > 0:
            self.year = new_year
        else:
            raise ValueError("Year must be positive")

    def add_days(self, days: int):
        current_date = date(self.year, self.month, self.day)
        new_date = current_date + timedelta(days=days)
        self.day, self.month, self.year = new_date.day, new_date.month, new_date.year

# Test cases to verify the solution correctness
def main():
    try:
        D = Date(20, 1, 2023)
        D.show()
        D.set_day(31)
        D.set_month(12)
        D.set_year(2022)
        D.show()
        D.add_days(40)  # Adding 40 days to 31-12-2022
        D.show()  # Expected output: 09-02-2023
        D.set_day(32)  # Should raise ValueError
    except ValueError as e:
        print(e)

main()
```

In the provided solution, the `Date` class is corrected and enhanced with the `add_days` method that correctly adds a specified number of days to the date. The `set_day`, `set_month`, and `set_year` methods include validation to ensure that the date remains valid. The test cases in the `main` function demonstrate the functionality of the class and its error handling.

