import click
from click import style
from click import unstyle

# Define a function to generate a title with an underline
def generate_title(text, underline_char='-', to_title_case=False):
    """Generate a title with an underline."""
    if to_title_case:
        text = text.title()
    underline = underline_char * len(text)
    return f"{style(text, fg='blue')}\n{underline}"

# Define a function to print text inside a box
def print_box(text, border_char='*'):
    """Print text inside a box."""
    lines = text.split('\n')
    max_length = max(len(line) for line in lines)
    box = border_char * (max_length + 2)
    click.echo(box)
    for line in lines:
        click.echo(f"{border_char} {style(line, fg='green')}{border_char}")
    click.echo(box)

# Define a function to simulate an evaluation process
class Evaluation:
    """Simulate an evaluation process."""
    def __init__(self, success=True, failed_commands=None):
        self.success = success
        self.failed_commands = failed_commands if failed_commands else []

# Define a function to print an evaluation summary
def print_evaluation_summary(evaluation):
    """Print a summary of the evaluation."""
    if evaluation.success:
        click.echo("Evaluation successful.")
    else:
        click.echo("Evaluation failed.")
        for command in evaluation.failed_commands:
            click.echo(f"Command '{command}' failed.")

# Define a function to print a detailed evaluation
def print_evaluation_detailed(evaluation):
    """Print a detailed evaluation."""
    if evaluation.success:
        click.echo("Evaluation successful.")
    else:
        click.echo("Evaluation failed.")
        for command in evaluation.failed_commands:
            click.echo(f"Command '{command}' failed.")

# Define the CLI commands
@click.group()
def cli():
    """Text Styling CLI."""
    pass

@cli.command()
@click.argument('text')
@click.option('--underline_char', default='-', help='Underline character.')
@click.option('--to_title_case', is_flag=True, help='Transform text to title case.')
def title(text, underline_char, to_title_case):
    """Print a title with an underline."""
    click.echo(generate_title(text, underline_char, to_title_case))

@cli.command()
@click.argument('text')
@click.option('--border_char', default='*', help='Border character.')
def box(text, border_char):
    """Print text inside a box."""
    print_box(text, border_char)

@cli.command()
@click.option('--verbose', is_flag=True, help='Print detailed evaluation.')
def evaluation(verbose):
    """Simulate an evaluation process."""
    evaluation = Evaluation(success=True)
    evaluation.failed_commands = ['command1', 'command2']
    if verbose:
        print_evaluation_detailed(evaluation)
    else:
        print_evaluation_summary(evaluation)

@cli.command()
@click.argument('evaluation')
def summary(evaluation):
    """Print a summary of the evaluation."""
    evaluation = Evaluation(success=True)
    evaluation.failed_commands = ['command1', 'command2']
    print_evaluation_summary(evaluation)

# Run the CLI
