        lines = [CellSeparatorLine(), StringLine("Hello"), CellSeparatorLine(), EmptyStringLine()]
        expected_lines = [DatabricksCellSeparatorLine(), StringLine("Hello"), DatabricksCellSeparatorLine(), EmptyStringLine()]
