import logging
from enum import Enum
from typing import Dict

# Define a logger to handle errors and debugging messages
logging.basicConfig(level=logging.INFO)
logger = logging.getLogger(__name__)

class DeviceState(Enum):
    """Enum to represent the state of devices"""
    AVAILABLE = 1
    UNAVAILABLE = 2
    ON = 3
    OFF = 4
    OPEN = 5
    CLOSED = 6

class Switch:
    """Class to represent a switch in the smart home system"""
    def __init__(self, name: str):
        self.name = name
        self.state = DeviceState.OFF

    def toggle(self):
        """Toggle the switch state"""
        if self.state == DeviceState.OFF:
            self.state = DeviceState.ON
        else:
            self.state = DeviceState.OFF

    def turn_on(self):
        """Turn on the switch"""
        self.state = DeviceState.ON

    def turn_off(self):
        """Turn off the switch"""
        self.state = DeviceState.OFF

class Cover:
    """Class to represent a cover in the smart home system"""
    def __init__(self, name: str):
        self.name = name
        self.state = DeviceState.CLOSED

    def open(self):
        """Open the cover"""
        self.state = DeviceState.OPEN

    def close(self):
        """Close the cover"""
        self.state = DeviceState.CLOSED

class SmartHomeSystem:
    """Class to represent the smart home system"""
    def __init__(self):
        self.devices: Dict[str, Switch] = {}
        self.covers: Dict[str, Cover] = {}

    def add_switch(self, name: str):
        """Add a switch to the system"""
        self.devices[name] = Switch(name)

    def add_cover(self, name: str):
        """Add a cover to the system"""
        self.covers[name] = Cover(name)

    def get_switch_state(self, name: str) -> str:
        """Get the current state of a switch"""
        if name in self.devices:
            return f"Switch {name} is {self.devices[name].state.name}"
        else:
            return f"Switch {name} not found"

    def get_cover_state(self, name: str) -> str:
        """Get the current state of a cover"""
        if name in self.covers:
            return f"Cover {name} is {self.covers[name].state.name}"
        else:
            return f"Cover {name} not found"

    def toggle_switch(self, name: str):
        """Toggle the state of a switch"""
        if name in self.devices:
            self.devices[name].toggle()
        else:
            logger.error(f"Switch {name} not found")

    def turn_on_switch(self, name: str):
        """Turn on a switch"""
        if name in self.devices:
            self.devices[name].turn_on()
        else:
            logger.error(f"Switch {name} not found")

    def turn_off_switch(self, name: str):
        """Turn off a switch"""
        if name in self.devices:
            self.devices[name].turn_off()
        else:
            logger.error(f"Switch {name} not found")

    def open_cover(self, name: str):
        """Open a cover"""
        if name in self.covers:
            self.covers[name].open()
        else:
            logger.error(f"Cover {name} not found")

    def close_cover(self, name: str):
        """Close a cover"""
        if name in self.covers:
            self.covers[name].close()
        else:
            logger.error(f"Cover {name} not found")

