        Raises:
            sqlite3.Error: If an error occurs while creating the table.
        """
        try:
            self.cursor.execute("""
                CREATE TABLE IF NOT EXISTS NotDelivered (
                    containerId TEXT PRIMARY KEY,
                    temperature INTEGER,
                    humidity INTEGER,
                    latitude REAL,
                    longitude REAL,
                    timestamp TEXT
                )
            """)
            self.conn.commit()
        except sqlite3.Error as e:
