                        'longitude': float
                    },
                    'timestamp': 'string'
                }

        Raises:
            sqlite3.Error: If an error occurs while inserting the record.
        """
        if not isinstance(data, dict):
            raise ValueError("Invalid data structure")

        required_keys = ['containerId', 'temperature', 'humidity', 'geo', 'timestamp']
        if not all(key in data for key in required_keys):
            raise ValueError("Missing required keys")

        if not isinstance(data['containerId'], str):
            raise ValueError("Invalid containerId type")
        if not isinstance(data['temperature'], int):
            raise ValueError("Invalid temperature type")
        if not isinstance(data['humidity'], int):
