                data['humidity'],
                data['geo']['latitude'],
                data['geo']['longitude'],
                data['timestamp']
            ))
            self.conn.commit()
        except sqlite3.Error as e:
            logger.error(f"Failed to insert record: {e}")

    def close(self):
        """
        Closes the database connection.
        """
        if self.conn:
            self.conn.close()

