import ase
from ase import Atoms
import numpy as np
import os
import re

class ConfigMaker:
    def __init__(self):
        self.configtypes = {}
        self.lattice_vectors = {}
        self.basis_atoms = {}
        self.box_dimensions = {}
        self.atom_type_mappings = {}
        self.atoms_list = []

        self.parse_configtypes()
        self.parse_config()

    def parse_configtypes(self):
        """Reads the CONFIGTYPES file and stores the configuration types."""
        configtypes_file = 'CONFIGTYPES'
        if not os.path.exists(configtypes_file):
            raise FileNotFoundError(f"CONFIGTYPES file not found: {configtypes_file}")

        with open(configtypes_file, 'r') as f:
            for line in f:
                line = line.strip()
                if line and not line.startswith('#'):
                    config_type, config_name = line.split()
                    self.configtypes[config_name] = config_type

    def parse_config(self):
        """Reads the LATVEC, BASIS, BOX, and TYPEMAP files to store lattice vectors, basis atoms, box dimensions, and atom type mappings, respectively."""
        files = ['LATVEC', 'BASIS', 'BOX', 'TYPEMAP']
        for file in files:
            if not os.path.exists(file):
                raise FileNotFoundError(f"{file} file not found")

            with open(file, 'r') as f:
                lines = f.readlines()

            if file == 'LATVEC':
                # Read lattice vectors
                lattice_vectors = []
                for line in lines:
                    line = line.strip()
                    if line and not line.startswith('#'):
                        lattice_vector = np.array([float(x) for x in line.split()])
                        lattice_vectors.append(lattice_vector)
                self.lattice_vectors['default'] = np.array(lattice_vectors)

            elif file == 'BASIS':
                # Read basis atoms
                basis_atoms = []
                for line in lines:
                    line = line.strip()
                    if line and not line.startswith('#'):
                        basis_atom = line.split()
                        basis_atoms.append(basis_atom)
                self.basis_atoms['default'] = basis_atoms

            elif file == 'BOX':
                # Read box dimensions
                box_dimensions = []
                for line in lines:
                    line = line.strip()
                    if line and not line.startswith('#'):
                        box_dimension = np.array([float(x) for x in line.split()])
                        box_dimensions.append(box_dimension)
                self.box_dimensions['default'] = np.array(box_dimensions)

            elif file == 'TYPEMAP':
                # Read atom type mappings
                atom_type_mappings = {}
                for line in lines:
                    line = line.strip()
                    if line and not line.startswith('#'):
                        atom_type, symbol = line.split()
                        atom_type_mappings[symbol] = atom_type
                self.atom_type_mappings = atom_type_mappings

    def add(self, symbols, positions, box):
        """Adds a new configuration to the list of Atoms objects."""
        if len(symbols) != len(positions):
            raise ValueError("Number of symbols and positions do not match")

