from django.shortcuts import render, redirect
from django.contrib import messages
from .forms import MovieForm, StudioForm, HallForm, CountryForm
from .models import Movie, Studio, Hall, Country

def index(request):
    """Displays the list of movies."""
    movies = Movie.objects.all()
    return render(request, 'movie_database/index.html', {'movies': movies})

def movie_detail(request, slug):
    """Displays detailed information about a specific movie."""
    movie = Movie.objects.get(slug=slug)
    return render(request, 'movie_database/movie_detail.html', {'movie': movie})

def movie_create(request):
    """Provides a form for creating a new movie entry."""
    if request.method == 'POST':
        form = MovieForm(request.POST, request.FILES)
        if form.is_valid():
            form.save()
            messages.success(request, 'Movie created successfully.')
            return redirect('index')
    else:
        form = MovieForm()
    return render(request, 'movie_database/movie_create.html', {'form': form})

def studio_create(request):
    """Provides a form for creating a new studio entry."""
    if request.method == 'POST':
        form = StudioForm(request.POST)
        if form.is_valid():
            form.save()
            messages.success(request, 'Studio created successfully.')
            return redirect('index')
    else:
        form = StudioForm()
    return render(request, 'movie_database/studio_create.html', {'form': form})

def hall_create(request):
    """Provides a form for creating a new hall entry."""
    if request.method == 'POST':
        form = HallForm(request.POST)
        if form.is_valid():
            form.save()
            messages.success(request, 'Hall created successfully.')
            return redirect('index')
    else:
        form = HallForm()
    return render(request, 'movie_database/hall_create.html', {'form': form})

def country_create(request):
    """Provides a form for creating a new country entry."""
    if request.method == 'POST':
