# fleet_vehicle_model.py

class Model:
    def __init__(self, name):
        self.name = name

class FleetVehicleModel(Model):
    def __init__(self, name, program_id=None):
        super().__init__(name)
        self.program_id = program_id
        self.program = None

    def assign_program(self, program):
        if not isinstance(program, VmsProgram):
            raise ValueError("Invalid program. Only VmsProgram instances are allowed.")
        self.program = program
        self.program_id = program.name

    def get_program_details(self):
        if self.program:
            return {
                "name": self.program.name,
                "services": self.program.services,
                "inspections": self.program.inspections
            }
        else:
            return None


class VmsProgram:
    def __init__(self, name):
        self.name = name
        self.services = []
        self.inspections = []

    def add_service(self, service):
        self.services.append(service)

    def add_inspection(self, inspection):
        self.inspections.append(inspection)


# tests.py

import unittest
from fleet_vehicle_model import FleetVehicleModel, VmsProgram

class TestFleetVehicleModel(unittest.TestCase):

    def test_assign_program(self):
        program = VmsProgram("Maintenance Program")
        program.add_service("Service 1")
        program.add_inspection("Inspection 1")

        vehicle = FleetVehicleModel("Vehicle Model")
        vehicle.assign_program(program)

        self.assertEqual(vehicle.get_program_details(), {
            "name": "Maintenance Program",
            "services": ["Service 1"],
            "inspections": ["Inspection 1"]
        })

    def test_assign_invalid_program(self):
        vehicle = FleetVehicleModel("Vehicle Model")
        with self.assertRaises(ValueError):
            vehicle.assign_program("Invalid Program")

    def test_get_program_details(self):
        program = VmsProgram("Maintenance Program")
        program.add_service("Service 1")
        program.add_inspection("Inspection 1")

        vehicle = FleetVehicleModel("Vehicle Model")
        vehicle.assign_program(program)

        self.assertEqual(vehicle.get_program_details(), {
            "name": "Maintenance Program",
            "services": ["Service 1"],
            "inspections": ["Inspection 1"]
        })

        vehicle.program = None
        self.assertIsNone(vehicle.get_program_details())

if __name__ == "__main__":
    unittest.main()
```

