from dataclasses import dataclass
from enum import Enum
from typing import Optional

# Define an Enum for the widget types
class WidgetType(Enum):
    DESCRIPTION_WIDGET = "description_widget"
    VALUE_WIDGET = "value_widget"
    CORE_WIDGET = "core_widget"

# Define a dataclass for the DescriptionWidget
@dataclass
class DescriptionWidget:
    description: str

# Define a dataclass for the ValueWidget
@dataclass
class ValueWidget:
    value: str

# Define a dataclass for the CoreWidget
@dataclass
class CoreWidget:
    pass

# Define a decorator for registering widgets
def register(widget_class):
    return widget_class

# Define the ColorPicker class
@register
class ColorPicker(DescriptionWidget, ValueWidget, CoreWidget):
    _view_name: str = "ColorPickerView"
    _model_name: str = "ColorPickerModel"

    def __init__(self, value: Optional[str] = "black", concise: bool = False, disabled: bool = False):
        self.value = value
        self.concise = concise
        self.disabled = disabled

    @property
    def value(self) -> str:
        return self._value

    @value.setter
    def value(self, value: str):
        if not self._is_valid_color(value):
            raise ValueError("Invalid color format")
        self._value = value

    @property
    def concise(self) -> bool:
        return self._concise

    @concise.setter
    def concise(self, concise: bool):
        self._concise = concise

    @property
    def disabled(self) -> bool:
        return self._disabled

    @disabled.setter
    def disabled(self, disabled: bool):
        self._disabled = disabled

    def _is_valid_color(self, value: str) -> bool:
        # Check if the value is a named color
        if value in ["black", "white", "red", "green", "blue"]:
            return True

        # Check if the value is a hex color code
        if value.startswith("#") and len(value) == 7:
            return True

        return False

# Test cases
import unittest

class TestColorPicker(unittest.TestCase):
    def test_valid_color(self):
        color_picker = ColorPicker(value="black")
        self.assertEqual(color_picker.value, "black")

    def test_invalid_color(self):
        with self.assertRaises(ValueError):
            ColorPicker(value="#InvalidColor")

    def test_hex_color(self):
        color_picker = ColorPicker(value="#FFFFFF")
        self.assertEqual(color_picker.value, "#FFFFFF")

    def test_concise(self):
        color_picker = ColorPicker(concise=True)
        self.assertTrue(color_picker.concise)

    def test_disabled(self):
        color_picker = ColorPicker(disabled=True)
        self.assertTrue(color_picker.disabled)

if __name__ == "__main__":
    unittest.main()
```

