```python
import random

class Gem:
    """Represents a single gem on the grid with its color and position."""
    def __init__(self, color, x, y):
        self.color = color
        self.x = x
        self.y = y

    def __repr__(self):
        return f"Gem({self.color}, {self.x}, {self.y})"


class Grid:
    """Represents the 8x8 grid of gems, responsible for managing the gems and handling game logic."""
    def __init__(self):
        self.gems = [[None]*8 for _ in range(8)]
        self.score = 0
        self.generate_grid()

    def generate_grid(self):
        """Generates a random 8x8 grid of gems."""
        colors = ['red', 'green', 'blue', 'yellow', 'purple', 'orange', 'pink', 'brown']
        for i in range(8):
            for j in range(8):
                self.gems[i][j] = Gem(random.choice(colors), i, j)

    def print_grid(self):
        """Prints the current state of the grid."""
        for row in self.gems:
            print(' '.join(str(gem.color) if gem else '-' for gem in row))

    def swap_gems(self, x1, y1, x2, y2):
        """Swaps two adjacent gems on the grid."""
        if self.gems[x1][y1] and self.gems[x2][y2]:
            self.gems[x1][y1], self.gems[x2][y2] = self.gems[x2][y2], self.gems[x1][y1]

    def check_match(self):
        """Checks if there are any matches on the grid."""
        for i in range(8):
            for j in range(6):
                if self.gems[i][j] and self.gems[i][j].color == self.gems[i][j+1].color == self.gems[i][j+2].color:
                    self.score += 1
                    self.gems[i][j] = self.gems[i][j+1] = self.gems[i][j+2] = None
        for j in range(8):
            for i in range(6):
                if self.gems[i][j] and self.gems[i][j].color == self.gems[i+1][j].color == self.gems[i+2][j].color:
                    self.score += 1
                    self.gems[i][j] = self.gems[i+1][j] = self.gems[i+2][j] = None

    def fall_gems(self):
        """Makes the gems above the empty spaces fall down."""
        for j in range(8):
            for i in range(7, -1, -1):
                if self.gems[i][j] is None:
                    for k in range(i-1, -1, -1):
                        if self.gems[k][j]:
                            self.gems[k][j], self.gems[k+1][j] = self.gems[k+1][j], self.gems[k][j]
                            break
                    else:
                        self.gems[i][j] = Gem(random.choice(['red', 'green', 'blue', 'yellow', 'purple', 'orange', 'pink', 'brown']), i, j)

    def is_game_over(self):
        """Checks if the game is over (no more moves possible)."""
        for i in range(8):
            for j in range(8):
                if self.gems[i][j]:
                    for x, y in [(i-1, j), (i+1, j), (i, j-1), (i, j+1)]:
                        if 0 <= x < 8 and 0 <= y < 8 and self.gems[x][y]:
                            return False
        return True


class Game:
    """Represents the game itself, responsible for managing the grid, scoring, and game state."""
    def __init__(self):
        self.grid = Grid()

    def play(self):
        """Starts the game."""
        while True:
            self.grid.print_grid()
            print(f"Score: {self.grid.score}")
            x1, y1 = map(int, input("Enter the coordinates of the first gem (x y): ").split())
            x2, y2 = map(int, input("Enter the coordinates of the second gem (x y): ").split())
            self.grid.swap_gems(x1-1, y1-1, x2-1, y2-1)
            self.grid.check_match()
            self.grid.fall_gems()
            if self.grid.is_game_over():
                print("Game Over!")
                break


if __name__ == "__main__":
    game = Game()
    game.play()
