import PySimpleGUI as sg
import hashlib
import getpass
import unittest
import os

# Initialize an empty dictionary to store accounts
accounts = {}

# Function to validate account number
def validate_account_number(account_number):
    if len(account_number) != 10 or not account_number.isdigit():
        return False
    return True

# Function to validate account holder's name
def validate_name(name):
    if len(name) < 2 or len(name) > 50:
        return False
    return True

# Function to validate initial deposit
def validate_initial_deposit(amount):
    try:
        amount = float(amount)
        if amount <= 0:
            return False
        return True
    except ValueError:
        return False

# Function to hash password
def hash_password(password):
    return hashlib.sha256(password.encode()).hexdigest()

# Function to open a new account
def open_account():
    layout = [
        [sg.Text('Account Number:'), sg.Input(key='account_number')],
        [sg.Text('Account Holder\'s Name:'), sg.Input(key='name')],
        [sg.Text('Initial Deposit:'), sg.Input(key='initial_deposit')],
        [sg.Text('Credit Limit:'), sg.Input(key='credit_limit')],
        [sg.Button('Open Account')]
    ]
    window = sg.Window('Open Account', layout)
    while True:
        event, values = window.read()
        if event == 'Open Account':
            account_number = values['account_number']
            name = values['name']
            initial_deposit = values['initial_deposit']
            credit_limit = values['credit_limit']
            if validate_account_number(account_number) and validate_name(name) and validate_initial_deposit(initial_deposit):
                if account_number in accounts:
                    sg.popup('Account already exists')
                else:
                    accounts[account_number] = {
                        'name': name,
                        'balance': float(initial_deposit),
                        'credit_limit': float(credit_limit),
                        'password': hash_password(getpass.getpass('Enter password:')),
                        'transactions': []
                    }
                    sg.popup('Account opened successfully')
                    break
            else:
                sg.popup('Invalid input')
        elif event == sg.WINDOW_CLOSED:
            break
    window.close()

# Function to access an existing account
def access_account():
    layout = [
        [sg.Text('Account Number:'), sg.Input(key='account_number')],
        [sg.Text('Account Holder\'s Name:'), sg.Input(key='name')],
        [sg.Text('Password:'), sg.Input(key='password', password_char='*')],
        [sg.Button('Access Account')]
    ]
    window = sg.Window('Access Account', layout)
    while True:
        event, values = window.read()
        if event == 'Access Account':
            account_number = values['account_number']
            name = values['name']
            password = values['password']
            if account_number in accounts and accounts[account_number]['name'] == name and accounts[account_number]['password'] == hashlib.sha256(password.encode()).hexdigest():
                sg.popup('Account accessed successfully')
                transaction_window(account_number)
                break
            else:
                sg.popup('Invalid account or password')
        elif event == sg.WINDOW_CLOSED:
            break
    window.close()

# Function to perform transactions on an accessed account
def transaction_window(account_number):
    layout = [
        [sg.Text('Account Balance: $2000.00')],
        [sg.Button('View Balance')],
        [sg.Button('Transfer')],
        [sg.Button('Request Credit Limit')]
    ]
    window = sg.Window('Transaction Window', layout)
    while True:
        event, values = window.read()
        if event == 'View Balance':
            sg.popup('Account Balance: $2000.00')
        elif event == 'Transfer':
            transfer_window(account_number)
        elif event == 'Request Credit Limit':
            request_credit_limit_window(account_number)
        elif event == sg.WINDOW_CLOSED:
            break
    window.close()

# Function to transfer funds from an accessed account
def transfer_window(account_number):
    layout = [
        [sg.Text('Bank Code:'), sg.Input(key='bank_code')],
        [sg.Text('Account Number:'), sg.Input(key='account_number')],
        [sg.Text('Account Holder\'s Name:'), sg.Input(key='name')],
        [sg.Text('Transfer Amount:'), sg.Input(key='transfer_amount')],
        [sg.Button('Transfer')]
    ]
    window = sg.Window('Transfer Funds', layout)
    while True:
        event, values = window.read()
        if event == 'Transfer':
            bank_code = values['bank_code']
            account_number = values['account_number']
            name = values['name']
            transfer_amount = values['transfer_amount']
            if validate_account_number(account_number) and validate_name(name) and validate_initial_deposit(transfer_amount):
                if bank_code == '1234' and account_number in accounts and accounts[account_number]['name'] == name:
                    accounts[account_number]['balance'] -= float(transfer_amount)
                    accounts[account_number]['transactions'].append(f'Transfer to {name} - ${transfer_amount}')
                    sg.popup('Transfer successful')
                else:
                    sg.popup('Invalid bank code or account')
            else:
                sg.popup('Invalid input')
        elif event == sg.WINDOW_CLOSED:
            break
    window.close()

# Function to request a new credit limit for an accessed account
def request_credit_limit_window(account_number):
    layout = [
        [sg.Text('New Credit Limit:'), sg.Input(key='new_credit_limit')],
        [sg.Button('Request Credit Limit')]
    ]
    window = sg.Window('Request Credit Limit', layout)
    while True:
        event, values = window.read()
        if event == 'Request Credit Limit':
            new_credit_limit = values['new_credit_limit']
            if validate_initial_deposit(new_credit_limit):
                accounts[account_number]['credit_limit'] = float(new_credit_limit)
                sg.popup('Credit limit updated successfully')
            else:
                sg.popup('Invalid input')
        elif event == sg.WINDOW_CLOSED:
            break
    window.close()

# Main function
def main():
    layout = [
        [sg.Button('Open Account')],
        [sg.Button('Access Account')]
    ]
    window = sg.Window('Banking Application', layout)
    while True:
        event, values = window.read()
        if event == 'Open Account':
            open_account()
        elif event == 'Access Account':
            access_account()
        elif event == sg.WINDOW_CLOSED:
            break
    window.close()

# Unit tests
class TestBankingApplication(unittest.TestCase):
    def test_validate_account_number(self):
        self.assertTrue(validate_account_number('1234567890'))
        self.assertFalse(validate_account_number('123456789'))
        self.assertFalse(validate_account_number('12345678901'))

    def test_validate_name(self):
        self.assertTrue(validate_name('John Doe'))
