```python
import wikipedia
import socket
import time

class TCPClient:
    def __init__(self, host, port):
        self.host = host
        self.port = port
        self.client = socket.socket(socket.AF_INET, socket.SOCK_STREAM)

    def connect(self):
        self.client.connect((self.host, self.port))

    def send(self, message):
        self.client.send(message.encode())

    def receive(self):
        return self.client.recv(1024).decode()

    def close(self):
        self.client.close()


def isValid(input_text):
    """Check if the input text contains the trigger word "Wikipedia"."""
    return "Wikipedia" in input_text


def handle(search_term):
    """Fetch Wikipedia summary and output the result."""
    try:
        summary = wikipedia.summary(search_term, sentences=3)
        return summary
    except wikipedia.exceptions.DisambiguationError as e:
        return f"Multiple pages found for '{search_term}'. Please specify the page title."
    except wikipedia.exceptions.PageError:
        return f"No Wikipedia page found for '{search_term}'."


def main():
    host = '127.0.0.1'
    port = 12345

    client = TCPClient(host, port)
    client.connect()

    while True:
        input_text = client.receive()
        print(f"Received input: {input_text}")

        if isValid(input_text):
            search_term = input("Enter a search term: ")
            if search_term.lower() == "wikipedia":
                print("Please enter a different search term.")
                continue
            result = handle(search_term)
            client.send(result)
            print(f"Sent result: {result}")
        else:
            client.send("Invalid input. Please type 'Wikipedia' to search.")
            print("Invalid input. Please type 'Wikipedia' to search.")

        time.sleep(1)  # Simulate delay

    client.close()


if __name__ == "__main__":
    main()
