**Reactor Grid Simulator**
==========================

This program reads reboot steps from a file, applies them to a 3D reactor grid, and counts the number of cubes that are on.

**Code**
```python
import re
import sys

class ReactorGrid:
    def __init__(self, size):
        self.size = size
        self.grid = [[[False for _ in range(size)] for _ in range(size)] for _ in range(size)]

    def apply_reboot_step(self, step):
        match = re.match(r'on x=(-?\d+)..(-?\d+),y=(-?\d+)..(-?\d+),z=(-?\d+)..(-?\d+)', step)
        if match:
            x1, x2, y1, y2, z1, z2 = map(int, match.groups())
            for x in range(max(-50, x1), min(51, x2) + 1):
                for y in range(max(-50, y1), min(51, y2) + 1):
                    for z in range(max(-50, z1), min(51, z2) + 1):
                        self.grid[x + 50][y + 50][z + 50] = True
        else:
            match = re.match(r'off x=(-?\d+)..(-?\d+),y=(-?\d+)..(-?\d+),z=(-?\d+)..(-?\d+)', step)
            if match:
                x1, x2, y1, y2, z1, z2 = map(int, match.groups())
                for x in range(max(-50, x1), min(51, x2) + 1):
                    for y in range(max(-50, y1), min(51, y2) + 1):
                        for z in range(max(-50, z1), min(51, z2) + 1):
                            self.grid[x + 50][y + 50][z + 50] = False
            else:
                print(f"Invalid reboot step: {step}", file=sys.stderr)

    def count_on_cubes(self):
        return sum(sum(sum(row) for row in plane) for plane in self.grid)

def main():
    try:
        with open('reboot_steps.txt', 'r') as f:
            reboot_steps = f.readlines()
    except FileNotFoundError:
        print("Error: File 'reboot_steps.txt' not found.", file=sys.stderr)
        return 1

    grid = ReactorGrid(101)
    for step in reboot_steps:
        grid.apply_reboot_step(step.strip())

    on_cubes = grid.count_on_cubes()
    print(f"Number of on cubes: {on_cubes}")

    return 0

if __name__ == '__main__':
    sys.exit(main())
```

**Usage**
---------

1. Create a file named `reboot_steps.txt` containing the reboot steps in the specified format.
2. Run the program using `python reactor_grid_simulator.py`.
3. The program will print the number of on cubes in the reactor grid.

**Note**
----

* The program assumes that the reboot steps file is in the same directory as the program.
* The program uses a 101x101x101 grid, where the coordinates range from -50 to 50 in all three dimensions.
* The program handles potential file reading errors and provides informative error messages.

