    def get_typed_value(self):
        return super().get_typed_value()

class TestSecure(unittest.TestCase):
    def test_secure_string(self):
        key = os.urandom(32)
        access_level = "admin"
        secure_string = SecureString("Hello, World!", key, access_level)
        self.assertEqual(secure_string.get_value(), "Hello, World!")
        self.assertEqual(secure_string.get_typed_value(), "Hello, World!")

