        access_level = "admin"
        secure_incomplete_date = SecureIncompleteDate(datetime.date(2022, 1, 1), key, access_level)
        self.assertEqual(secure_incomplete_date.get_value(), "2022-01-01")
        self.assertEqual(secure_incomplete_date.get_typed_value(), datetime.date(2022, 1, 1))

    def test_access_denied(self):
