    @staticmethod
    def capabilities() -> List[str]:
        return [CAPABILITY_IMPORT, CAPABILITY_EXPORT]

# Plugin manager class
class PluginManager:
    def __init__(self):
        self.plugins: Dict[str, Plugin_v1] = {}

    def register_plugin(self, version: str, plugin: Plugin_v1):
